/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220307-3","meetingId":"r04-c-budget","date":"2022年3月7日","dateIso":"2022-03-07","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時２８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を150件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５号議案、令和４年度品川区一般会計予算","agenda":"第５号議案、令和４年度品川区一般会計予算","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"おはようあります。私からは、１８９ページ、生活安全推進事業、関連して１７３ページの国際交流推進事業、これはロシアとウクライナの話をメインで、あと１７９ページの働き方改革推進事業についてお伺いしたいと思います。ぜひこの１週間の変化を捉えていただいて、品川区としても、ロシアの侵攻に対して抗議の意を表していただければと思いますが、ご見解をお聞かせください。","respondent":"古巻総務課長","answer":"国内外の動きを見ますと、様々な形での抗議の動きが出ていますし、今、議会でもそういった形での動きがあるということを踏まえますと、区といたしましても、やはり何らかの意思表示をしていくのが妥当なのかというふうなことは、今、考えておりまして、今後。","voiceIndex":6,"id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問","question":"非常に前向きなご答弁をありがとうございました。対外的な態度表明については、これで質問を終わりますが、区内の動きについて職責といいますか、これについて幾つかお伺いしたいと思います。品川区では大使館、あと領事館も含めると約１５だったと思いますが、様々な国の大使館・領事館があると思います。","respondent":"古巻総務課長","answer":"特段大きな混乱はなかったとは認識しておりますけれども、今後も、区内にベラルーシ大使館があるということを踏まえまして、その動きについては注視してまいりたいと考えております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問","question":"今、ベラルーシがいい・悪いという話ではなくて、大使館に対して、やはりいろいろなデモの対象になりやすいところですから、大崎警察署など警察署から情報提供があってしかるべきなのだろうと私は思っていて、例えば第三日野小学校などのすぐ裏に大使館があったり、五反田周辺だけではなく、学校の近くに大使館があるというところが、結構、いろいろあると思うのです。","respondent":"古巻総務課長","answer":"ご指摘いただいたとおりでございまして、何かあった後では遅いということがありますので、危機管理的な側面からも、警察との連携はしっかりして、今後もそういった形での大使館をめぐる動きについてはしっかりと情報収集をした上で対応していきたいと考えております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"前向きなご答弁ありがとうございました。重ねて人権啓発のところから、いじめ防止というところでもお伺いするのですが、今、ロシア大使館もしくはベラルーシ大使館、ロシアの国、ベラルーシの国に対しては、品川区として、もしくは日本として、非難の決議を出していくといった動きがあると思うのですが、ただ、ロシア人が悪いというわけではなく、在日ベラルーシ人が悪いというわけではないと思うのです。","respondent":"古巻総務課長、島袋人権啓発課長","answer":"ベラルーシに関しましては、ロシアと同調してみたいな話もありますけれども、状況の分析は、まだまだこれからどうなるか見通せないところがありますので、場合によっては。人権啓発課では、このたび、「外国人差別は許さない」という懸垂幕を掲出する予定ですので、それを区民の皆様に見ていただくように努めてまいりたいと考えております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"大使館については、私も今、思い出したのですが、今回の質問をつくるに当たっていろいろ見ていく中で、ネットの中、ほぼＳＮＳでは、ベラルーシ大使館の警備が手薄でチャンスだというような呼びかけ等もあって、やはり区内の出来事ですから、ぜひ注視していただいて、警察と強く連携していただければと思います。職員の働く環境についてどういった配慮をされているのか、お聞かせください。","respondent":"崎村人事課長","answer":"安全衛生管理上、委員からガイドラインのお話がございましたけれども、人事課といたしましても、職員の情報機器作業従事者の健康診断や、あと毎月、全職員向けに行っています安全衛生管理研修の中でも、そういった情報機器作業の中で取り組むべき事項。","voiceIndex":15,"id":"exchange-005"},{"speaker":"芹澤委員","kind":"意見","question":"多分、椅子も机も一括で購入されていらっしゃると思いますので、ある程度は仕方ないと思うのですが、やはり、それぞれの体格に合わせた椅子、それぞれの体格に合わせた机。机はこれぐらいだよ。それで、課長に関しても恐らくそうだと思うのですが、課長のＩＣＴスキルを次の課長に引き継げるような取組みというのが必要かと思うのですが、そういった取組みに今どういうものがあるのか、お聞かせください。","respondent":"崎村人事課長","answer":"職員のＩＣＴスキルの引継ぎ、特に課長の引継ぎというところです。現在、特に取り組んでいるところはないですけれども、先ほど冒頭に予算の説明がございましたが、今後区としてＤＸを進めていくに当たって、やはりそれを推進していく職員の育成というのが重要になってまいります。","voiceIndex":17,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問","question":"おはようあります。東京２０２０大会のレガシーの取組みで、地域特性を活かしたアート活動の場所、またパラスポーツの拠点ということで掲げられておりますが、新規事業で、品川区がプレス発表しております、知的障害がある方向けにアートの街“天王洲”などの資源を活用し、アートの講座を実施する、この講座との関連性をお伺いいたします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員にご指摘いただいた、障害者アート等との連携ですが、アートの活動拠点としての使い方ということでは、アートの種類や特性等には特にこだわらないで、いろいろな形で活用できればと考えております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。知的障害者の方の作品はとても、本当に感動的です。暫定活用ではありますけれども、こういう活動の場を一つでも多くつくっていただくことを要望します。続きまして、八潮地区のまちづくり事業について伺います。八潮団地は入居から間もなく４０年を迎えようとしております。この新設された経緯と事業内容をお知らせください。","respondent":"川島地域活動課長","answer":"八潮まちづくり担当の組織新設の経緯というようなところですが、今、委員にご説明いただきましたが、昭和５８年に団地の入居が始まったということで、約４０年経過しています。","voiceIndex":22,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"この２年間、コロナ禍の影響を受けて、なかなかワークショップが延期、延期になっております。アンケートの結果も書面での報告となっておりまして、このような状況もありますけれども、こちらのまちづくりガイドラインの策定に向けての取組みの関連と、また八潮地域は、八潮自治会、１つの自治会で八潮地域センターがありますけれども、この地域センターとの関連をお伺いいたします。","respondent":"川島地域活動課長","answer":"例えば今、都市計画課で進めている取組み等は、そのまま引き続き継続していただく中で、八潮まちづくり担当は住民との調整を行いながら、区役所の組織に横串を刺しまして、組織連携を進めていくような役割になるかと考えています。","voiceIndex":24,"id":"exchange-009"},{"speaker":"新妻委員","kind":"提案","question":"続きまして、パートナーシップ制度について伺います。この報告書の中では、「レインボー宣言しながわ」の提案や、パートナーシップ制度の早期導入などが具体的に示されております。一つひとつ、着実に実現されることを要望いたします。簡単に東京都のご説明をお願いいたします。併せて、東京都がこの制度を導入することで、品川区に住むＬＧＢＴＱの方々にはどのようなメリットがあるのか、お伺いいたします。","respondent":"島袋人権啓発課長","answer":"区に関しましては、やはり制度ができても、アンコンシャス・バイアスという、思い込みや偏見による差別がまだまだ多い状況だと考えておりますので、特別講座に関しましては、そのような方たちに来ていただき、子どもから大人。","voiceIndex":26,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問","question":"東京都がパートナーシップ宣言を発令することで、品川区民が、これに準じて、この制度を利用できるということが望ましいと考えております。今ご説明がありました都営住宅への入居、入院に関すること等々ありますけれども、そうしますと、東京都が発令することで、それに準じて品川区もしっかり対応されるという理解でよろしいのでしょうか。その辺のことについて、ご答弁をお願いいたします。","respondent":"島袋人権啓発課長","answer":"ただいま東京都より、東京都パートナーシップ宣誓制度導入に当たりまして、区市町村の調査というものが来ておりますので、委員がご指摘の内容についても検討していくように進めてまいりたいと考えているところです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"横山委員","kind":"質問","question":"私からは、１６６ページ、広報広聴費、１７６ページ、人権啓発費、１９９ページ、プロスポーツ連携事業、２０８ページ、選挙費、時間があれば１７１ページのＩＣＴ推進管理費についてお伺いいたします。一般質問でもお伺いしたのですけれども、選挙におけるハラスメントの防止対策について、有権者への啓発行動として、現在、区が実施している内容をお聞かせください。","respondent":"齋藤選挙管理委員会事務局長、島袋人権啓発課長","answer":"選挙管理委員会で実施している研修ですが、講座・研修会とも、地方自治に関心を持っていただくための講座、しいの木講座や、投票率向上に向けての出前模擬選挙といった講座・研修会を実施しています。人権啓発特集号を年２回発行しておりまして、啓発に努めているところです。","voiceIndex":31,"id":"exchange-012"},{"speaker":"横山委員","kind":"質問・要望","question":"６ページの調査概要です。８ページをお願いいたします。１０ページをお願いいたします。ハラスメントは重大な人権侵害であり、区民向けに、パワハラ、セクハラ、マタハラなどハラスメントの現状や取組みについて意識啓発を進めることが重要と考えていますが、人権侵害の観点から、どのように区民の意識を向上させていくのがよいとお考えでしょうか。質問の部分、ご答弁をお願いいたします。","respondent":"島袋人権啓発課長","answer":"区民に対しましても、やはり啓発活動をしっかり進めてまいりたいと考えておりますし、１１月１２日から２５日に関しましては、女性に対する暴力をなくす運動の期間です。このときにも、様々な女性の人権に対する問題を提議していきたいと考えているところです。","voiceIndex":34,"id":"exchange-013"},{"speaker":"横山委員","kind":"質問・要望","question":"引き続き、啓発をよろしくお願いいたします。２点目に、プロスポーツ連携事業についてお伺いいたします。私は２月に、佐野智郎ヘッドコーチにお話を伺いました。このチームはまだスタートしたばかりですから、伸び代があるチームで、区民としてとても応援のしがいがあり、選手やチームと共に、私自身も応援する側として、応援を楽しみながら一緒に成長していきたいと考えています。","respondent":"中元スポーツ推進課長","answer":"令和３年に誕生した、区をホームタウンとするプロスポーツチームと連携し、小学生を対象としたスポーツ教室を今年度も実施していただきましたが、来年度も引き続き予算計上させていただいたものです。","voiceIndex":36,"id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"渡部委員の一般質問にもあったのですけれども、私たちの会派で北海道に視察に伺い、北海道日本ハムファイターズの方から、地域と融合したプロスポーツとして、北広島市に建設中のボールパーク構想についてご説明いただきました。庁舎移転後の跡地活用として、民間活力をどのように活かしていくかを含めてご検討いただきたいと要望いたしますが、区のご見解をお聞かせください。","respondent":"佐藤計画担当課長","answer":"庁舎移転後の跡地活用につきましては、大井町エリアのさらなるにぎわい向上のため、多くの集客が可能な多目的の施設が必要と考えております。委員ご指摘の整備手法等を含めまして、様々な観点から検討してまいります。","voiceIndex":38,"id":"exchange-015"},{"speaker":"横山委員","kind":"質問","question":"まだ少し先のことですので、様々な民間活力の活かし方など、研究・検討を進めていただけたらと考えています。では３点目に、広報広聴費についてお伺いいたします。そして４点目ですけれども、ＩＣＴ推進管理費についてお伺いいたします。令和７年度末までに可能な手続きは全てオンライン化するとしておりますが、令和４年度から令和７年度までの、現時点での計画についてお聞かせください。","respondent":"大澤広報広聴課長、宮澤情報推進課長","answer":"ホームページにおきましては、それぞれの事業の目的と、また詳しい内容についてご案内して、区民の皆様に伝わるように努めております。手続きの中では、手数料がかかったり対面での交付、押印といった課題もありますので、その辺も含めてどういった形でオンライン化できるかというのを、庁内で検討を進めていくというところで、令和７年度までに。","voiceIndex":40,"id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"オンライン化の促進について、ありがとうあります。たくさん申請があるところから進めていただくということで、こちらはぜひ、本当に大変な作業になってくるかと思うのですけれども、喜ばしいことですし、少しずつ進めていただきたいと考えていますので、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-017"},{"speaker":"安藤委員","kind":"提案","question":"新庁舎整備基本構想・基本計画策定委員会の中で、新庁舎の高層・低層という話も、高層でいいのでしょうかという。公有地というのは区民の財産なわけですから、区が一方的に、ここをにぎわい施設にするということを決めるのは、私は間違っていると思いますし、にぎわい施設を造ってほしい、造るかどうかということを、区民に一度でも、真っさらな状態で問うたことはあるでしょうか。","respondent":"佐藤計画担当課長","answer":"この方針を策定する段階におきましては、案を含めまして、区民の方にご提示した上でご意見いただきながら方針を策定してきたという経緯があります。今後につきましても、様々な観点から検討してまいりたいと考えています。","voiceIndex":45,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、現庁舎の跡地も含めた大井町の区有地ににぎわい施設を造るという方針を、直接区民に問うたことがあるのですかということです。区民が、「ここににぎわい施設を造るのです」という区の方針を見て、「いいですね。造ってほしい」という意思表示をしたということは、私はないと思っているのです。その辺をちゃんとしっかりお答えいただきたいと思います。","respondent":"佐藤計画担当課長","answer":"繰り返しにはなりますけれども、大井町駅周辺地域まちづくり方針におきまして、行政機能・にぎわい集積ゾーンという形で、今後の活用方法についてお示しした上で、ご意見いただきながら方針を策定してきたということがありますので、委員ご指摘の。","voiceIndex":47,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"１７７ページ、男女共同参画推進事業について、パートナーシップ制度、区職員の休日や福利厚生について、それぞれ伺いたいと思います。先ほども質疑がありましたが、品川区としてパートナーシップ制度を設置する考えを持っていただきたいと思いますが、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"品川区におけるパートナーシップ制度の早期導入ですが、第１７期品川区行動計画推進会議の報告書を受け、速やかに実施する方向で検討してまいりたいと考えているところです。","voiceIndex":51,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"速やかに検討していただけるということで、たくさんの会派からも要望がありましたので、ぜひ今年度、検討を進めていただきたいと思います。その上で具体的に伺いますが、区職員の休日につきまして、区職員が結婚すると、何日間の休日があるのか、伺いたいと思います。その上で、異性カップルだけではなく同性カップルにもこの休日を認めるべきだと思いますけれども、いかがでしょうか。","respondent":"崎村人事課長","answer":"ここで言います結婚というのは、現在は民法上の婚姻というのを意味しておりまして、いわゆる法律婚を前提としておりますので、先ほども都の制度の紹介のお話がございましたけれども、区として、パートナーシップ制度についての方向性を総合的に検討する中で。","voiceIndex":53,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"パートナーシップ制度の動向を見ながら検討していきたいということであります。この間、様々議論がされてきましたけれども、区の職員は結婚に伴い、７日以内の休暇があります。品川区としても、そこをどのようにお考えなのか、伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"品川区に関しましては、先ほど申し上げました第１７期品川区行動計画推進会議の報告書を受け、できるところからやっていけるように努力していきたいと考えているところです。","voiceIndex":55,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"昨年末に報告書が出て具体化はこれからということですので、ぜひ進めていただきたいと考えていますが、この休日の規定は条例が根拠になっているのです。その上で、なぜ結婚すると７日以内の休日が与えられるのか。そこの条例上の趣旨というのはどういうことなのか。お祝いという意味なのか。それについて伺いたいと思います。","respondent":"崎村人事課長","answer":"委員からお話がありましたように、結婚休暇につきましては、結婚後の新婚旅行等々の面もございまして、７日以内の休暇を認めているといったところです。","voiceIndex":57,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこはやはり、異性カップルも同性カップルも同等に与えられるべきだと思います。次に、福利厚生について伺いたいと思います。結婚や、配偶者の死亡の際に、幾ら給付されるのか、伺いたいと思います。この点についても給付の対象を異性カップルに限定するのではなく、同性カップルも対象にすべきだと思いますけれども、いかがでしょうか。","respondent":"崎村人事課長","answer":"どちらも、先ほどご説明させていただきましたが、法律婚等を前提に制度設計をしておりますが、パートナーシップ制度導入についての検討の中で、職員の福利厚生について、この給付金のみならず、福利厚生全般についても併せて検討していくべきものと考えております。","voiceIndex":59,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"これまでは法律婚が前提とされていたけれども、今後は、給付金のみならず全体的に検討していきたいという答弁を頂きました。昨年１２月の報告書に沿って、パートナーシップ宣言、また区職員の待遇、品川区の職員の休暇や給付金を、同性カップルも対象にすれば、当然、民間企業への波及効果も期待されると思います。ぜひ、そういう趣旨も踏まえて、今後、具体化していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-025"},{"speaker":"くにば委員","kind":"提案","question":"予算特別委員会の取り決めに従いまして、理事者の皆様には、この場でのホームページの閲覧は求めません。総論に関しては総括質疑でするとして、本日は４０以上の項目にわたって指摘・提案・要望をします。一番右側の部分です。これがなぜか、９つのメニューの「手続き・届出」と「施設案内」の間に入ってしまっていて、恐らくミスだと思いますので、ここに関しては改善を要望いたします。下から４番目です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-026"},{"speaker":"くにば委員","kind":"意見","question":"先日、つる委員が、主に１回の答弁で、あとは思いを語っていらっしゃったと思いますので、これに関しましては私も、基本的に私がお伝えしようと思っている部分に関してお話しします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-027"},{"speaker":"くにば委員","kind":"質問・要望","question":"「防災・くらしの安全」というページが最も見やすいのですが、ここにもリンク切れが１つありますので、これに関しましては後ほど直接お伝えします。高齢者の施設のページでは、それぞれの情報に関して、どういった内容なのかというのを説明していますので、それに関して個別に説明したほうが、このページを見た方は分かりやすいと思います。これは恐らくミスだと思います。ぜひともご確認をお願いします。","respondent":"大澤広報広聴課長","answer":"広報広聴課で一括に管理するということは、１万６,０００ページという量から考えても難しいと考えております。見やすいホームページにする調整というのが大切だと思いますので、今後、研修等を通して周知してまいりたいと思います。","voiceIndex":67,"id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"ページがどこに該当するか分からないですが、感染症に関する区の検証・記録の在り方について、ほかに、１７３ページ、非核平和都市品川宣言事業、１６６ページ、広報広聴費、ホームページ等経費、２０８ページ、選挙費、１７７ページ、「みんなのひろば」、１８９ページ、児童見守りシステム運営費、２０１ページ、旧東品川清掃作業所暫定活用について伺います。感染症対策の記録について伺います。","respondent":"古巻総務課長","answer":"感染症対策に関する記録ですけれども、当然、区では、これまで４０回以上、新型コロナウイルス感染症対策本部会議を行ってまいりまして、それを通じて、記録としてきちんと文書化されたもの、これは内部資料になりますけれども、それを取って。","voiceIndex":70,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"非核平和都市品川宣言事業について伺います。そのことに関するパネル展示が用意されているのかを、まず伺います。現状を危惧し、不安を訴える市民の声が生活者ネットワークには届いています。世界の非核兵器地帯についても、パネル展示やホームページなどで周知し、世界では非核を実現できている地域があることを示し、区民が希望を持てる事業に発展させていただきたいと要望いたしますが、見解を伺います。","respondent":"古巻総務課長","answer":"平和パネル展ですけれども、これまでも毎年、併せていろいろとしていますし、また平和人権パネル展示等もしていますけれども、特に、何というのですか、特定の地域の、そういった非核に関してというところは、パネルとして、あまり現状、していないかと思いますけれども。","voiceIndex":72,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"歳入の際にも触れましたが、区のホームページの各事業を紹介するページでは、事業計画や事業の根拠法、条例、要綱を載せてほしいと求めますが、見解を伺います。「区政情報」の欄に、計画一覧を設けてほしいです。見解を伺います。なぜこのような事態となってしまったのか、都市計画審議会に限らず、傍聴ができる会議体でこのようなことが起きないように再発防止を求めたいのですが、見解を伺います。","respondent":"東野経理課長、大澤広報広聴課長","answer":"現在、こちらのページにつきましては、どの段階まで掲載が可能かどうかというところを整理している段階でございまして、今後も引き続き検討していきたいと考えています。計画一覧と、役に立ったかどうかということに関しては、今後検討してまいります。","voiceIndex":74,"id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"例として都市計画審議会について挙げたのですけれども、イベントカレンダーに、傍聴ができる会議体のことが記されていなかったことが問題だったので、その再発防止をどのように考えているかと伺いました。ご答弁ください。","respondent":"大澤広報広聴課長","answer":"各所管からの記載漏れがないように確認してまいります。","voiceIndex":77,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"ほかの部分も、まず契約に関しては前向きに検討をお願いいたします。事業の名前によっては、要綱・条例などと全くリンクしないものなどがありますので、ぜひ前向きに検討していただきたいと思います。昨年の第４回定例会で、選挙公報のスペースの拡充について質問しました。選挙管理委員会委員長から、事務方に督促して検討するようにしてまいりたいとありましたが、現在の検討状況をお知らせください。","respondent":"齋藤選挙管理委員会事務局長","answer":"区議会議員選挙での選挙公報です。今、レイアウトは、新聞紙の大きさの１つのページに、１５人の候補者の方の公報をお知らせすることにしておりますが、２月末の選挙管理委員会で、１２人ということで、若干広めの形でご案内できるように、改善の方向で決定したところです。","voiceIndex":79,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"期待しております。では、次に行きます。旧東品川清掃作業所暫定活用についてです。先ほどもありましたが、パラスポーツを中心とした活用とのことでした。しかし、暫定活用とあります。なぜ暫定なのか。障害者が利用できる施設は継続してほしいという意味で、暫定の考え方を伺います。併せて、暫定期間はいつまでなのか。そして、行政財産から普通財産に変更するのかも伺います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらは、将来的な利用方法についてはともあれ、まず東京２０２０大会のオリンピックレガシーをいち早く継承しようということで、暫定的に使うというものです。期間は５年程度を考えております。財産的な区分の扱いとしては、行政財産です。","voiceIndex":81,"id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"要望でとどめます。「みんなのひろば」について伺います。性的マイノリティ向けの交流広場「みんなのひろば」です。例えば、子どもが高学年から「みんなのひろば」に参加できたら、人権についての理解がさらに進むのではないかと考えますが、開催日の日程は、今後も学校のない日が設定されていくのか、伺います。高学年や中学生への参加呼びかけを行っているのか、周知方法を伺います。","respondent":"島袋人権啓発課長","answer":"まだまだ差別意識についてのお悩み等がありますので、こちらは参加人数が少なくとも、しっかりと継続して実施してまいりたいと考えているところです。","voiceIndex":83,"id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ、基本は子どもたちにも情報が届くようにしていただきたいと要望いたします。子どもが危険を感じたら、ブザーを引いていい、助けを求めていいというのが、まもるっちの趣旨だと思うのですが、区と区教育委員会の認識が違うのか、伺います。新１年生に貸与されるまもるっちの資料一覧を確認したところ、オプション機能の通話機能をつけた人はココセコムサービスも追加できると、案内が入っています。","respondent":"森田生活安全担当課長","answer":"プロポーザルでＫＤＤＩに委託業務ということになりましたが、まもるっちにつきましては、この機能を利用しているところではありますが、私たちの、まもるっちセンターにつきましては、午前７時３０分から午後８時までということになっておりますので。","voiceIndex":85,"id":"exchange-036"},{"speaker":"田中委員","kind":"確認","question":"まもるっちのチラシには、地域で児童を見守る、万が一のときは児童の保護や付近状況の確認をお願いするものとありますが、ココセコムのオプション導入は区の目的に合致しているとお考えでしょうか。区の見解を伺います。そして、２０２０年９月２３日文教委員会の議事録で、２０２３年度に新システムに移行する予定があり、新しいまもるっちの在り方を２０２１年度に検討すると確認しました。伺います。","respondent":"森田生活安全担当課長","answer":"後継機の関係ですが、今現在、検討しています。会議体がありますかということですが、これは今のところ、係内での検討を進めておりますし、委託継承のところともお話をしています。","voiceIndex":87,"id":"exchange-037"},{"speaker":"木村委員","kind":"確認","question":"総務費の中の、最初に１６７ページの上から４行目、広報経費からの質問です。間違いがあるかもしれませんが。年間３９回発行していますけれども、希望者には各家庭に配布しているかと思います。配達の場合は、厚さによってページ数が違ってきますけれども、これにつき、配達する人、配達員というのか、そういう方々に配られるお金というものに違いがあるのかどうか、確認します。","respondent":"大澤広報広聴課長","answer":"様々な調査におきましても、広報紙から情報を得るという方が、現時点でも一番ですので、それなりの役割を果たしているものと認識しています。個別配送ですが、こちらは、お申込みがあった方のご自宅の郵便受けに配送業者が入れているものです。","voiceIndex":90,"id":"exchange-038"},{"speaker":"木村委員","kind":"質問","question":"区内で個別配送希望者の方はどれぐらいいるのか。個別配送希望者、スタンドに置く部数と合わせてどのぐらいの部数になるのかが分かれば教えてください。","respondent":"大澤広報広聴課長","answer":"現在、個別配送をしているのは約３,０００件となっておりまして、これは毎年度、少しずつですが、増加しています。広報紙の数ですけれども、現在、新聞折り込みが令和４年度予算では９万部と計算しております。発行数が１１万４,０００部です。","voiceIndex":92,"id":"exchange-039"},{"speaker":"木村委員","kind":"質問・要望","question":"一人でも多くの区民に現在の品川区の現状を知っていただきたいとの思いで発行しておられますけれども、この思いに反して、発行部数のうちどのぐらいが廃棄になっていると思われますか。質問が違いますけれども、その下にありますけれども、「声の広報」、３９回ということでありますけれども、声ということですから、ラジオか何かを利用したシステムでよろしいのか。これもお願いいたします。","respondent":"大澤広報広聴課長","answer":"例えばコンビニエンスストアに置かれている広報紙については、最後の残数までは今のところ確認できておりませんので、廃棄数について詳細は分かっていませんけれども、号によってやはり違いがあって、駅のスタンドなどは足りなくなるような号もありますので。","voiceIndex":94,"id":"exchange-040"},{"speaker":"木村委員","kind":"質問・要望","question":"１０月１日を品川区民憲章の日として、はや４０年になろうとしている事業と伺ってきましたけれども、令和４年で４０周年ということですが、これまではどのような周年行事を行ってきたのか、お聞かせください。そして、今年は４０周年と大きな節目ですから、何か大きな催物というものが行われる予定でしょうか。これもお聞かせください。","respondent":"大澤広報広聴課長","answer":"来年度、４０周年を迎えますので、区民の皆様に区民憲章の内容を再認識していただきたいという思いから、広報紙の特集号を発行する予定です。改めて、品川区民憲章について分かりやすく紹介できればと考えています。","voiceIndex":96,"id":"exchange-041"},{"speaker":"木村委員","kind":"質問","question":"しながわ百景からの質問を致しますけれども、しながわ百景の理念というのは何でしょうか。続けてまいります。しながわ百景は、いつ頃どのように選定されたのでしょうか。品川区のよさや誇れるところを区内外に発信していますけれども、現在の品川区が発信に力を入れたいところは、どのようなところなのか、お聞かせください。","respondent":"大澤広報広聴課長","answer":"区民の皆さんから推薦していただいた風景を投票によって決めたものです。品川区のよさですが、区民と共に魅力発信をすることが大切だと考えておりますので、これからも一緒にやっていきたいと考えています。","voiceIndex":98,"id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"私からは、１８５ページ、地域美化推進補助、および１８９ページ、歩行喫煙防止推進経費に関連して、喫煙のほうではなく、空き缶等の回収容器についてお伺いしたいと思います。１７７ページの人権啓発事業について伺います。空き缶等の回収容器についてですが、昨年の決算特別委員会で、藤原委員より、区内の自動販売機に空き缶等の回収容器が設置されていないという指摘がございました。","respondent":"森田生活安全担当課長","answer":"その場合の対応ですが、これにつきましては、日本自動販売協会という協会がありますので、回収箱の設置など、環境についても配慮してやっていただきたいところは要望しています。","voiceIndex":101,"id":"exchange-043"},{"speaker":"松本委員","kind":"質問","question":"第１４条１項で、違反者に対する改善命令というところまで定められているのですけれども、この改善命令が実際に出されたことというのはあるのでしょうか。伺います。","respondent":"森田生活安全担当課長","answer":"委員の説明のとおり、改善命令の項目があります。現在まで、この改善命令を出したことはございません。","voiceIndex":103,"id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"改善命令というのは、今も１件も事例がないと。条例が定められてもうかなり経ちますけれども、１回も改善命令は出されたことがないということです。本当は勧告から入ったほうがいいと私も思っているので、これは勧告の規定を設けたほうがいいのではないかと思うのですが、いかがでしょうか。","respondent":"森田生活安全担当課長","answer":"その上で様々な対応もしておりますところで、そこで改善もなされるのかと考えています。勧告も入れたほうがいいというお話ですが、これにつきましては、各区などの効果などもはかりながら、これから研究してまいりたいと考えています。","voiceIndex":105,"id":"exchange-045"},{"speaker":"松本委員","kind":"質問・要望","question":"そうですよね。どこにあるかというところまでは確認していない。ですので、当区においても、これはちょっとなかなか面白いのですけれども、条例上は空き缶の条例ではなく、廃棄物処理のほうの条例になってしまうのですけれども、ここは所管が違うとは思いますけれども、そこの部分は連携して届出制というのも検討していただきたいと思いますが、いかがでしょうか。","respondent":"森田生活安全担当課長","answer":"他の区では届出制があるです。他の区の情勢も含めてですけれども、その効果がどのようになっているかといったものも、他の区の担当者にもお伺いしながら、品川区で環境美化が悪化しないような方向を常々考えながら、調査・研究してまいりたいと思います。","voiceIndex":107,"id":"exchange-046"},{"speaker":"松本委員","kind":"質問・要望","question":"ありがとうございました。これらの講演会について、私も令和２年の決算特別委員会で取り上げさせていただいて、趣旨・目的のところは確認させていただきました。区民に絞っていなくて、誰でも参加できると。これはやはり、憲法・人権というのは区民に対してまずしっかりとやっていただくというのが大事だと思っているので、講演の対象は区民に絞ったほうがいいと思うのですが、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"たまたま、林家たい平さんの場合はファンが多いということから、地元の方が応募されたという話を披露させていただいたということでございまして、今でも区民の方・区内事業者の方を中心に応募していただいております。","voiceIndex":109,"id":"exchange-047"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、１６７ページ、広報経費と、それから１７３ページ、成人式経費についてお伺いします。広報経費からお願いいたします。そこで、観光の観点と併せて、例えば品川区の観光大使でありますシナモロールにワンストップのチャットボットとして、区のホームページにアクセスされる方をお出迎えしていただくというのはいかがでしょうか。","respondent":"大澤広報広聴課長","answer":"シナモロールの活用につきましては、いろいろ事業者との協議が必要であったり、また版権などのコスト面の課題もありますが、例えばチャットボットの活用の促進になるという面もあるかと思いますので、今後の可能性については検討してまいりたいと考えております。","voiceIndex":114,"id":"exchange-048"},{"speaker":"湯澤委員","kind":"質問","question":"チャンネルを開くとトップ画面にハタチの龍馬がアップされていて、やはり人気があって、わずか３日ぐらいで２,７００回の視聴再生となっていました。全て思いの籠もった作品だとは思うのですけれども、これは知ってほしい、ＰＲしたいという動画は、トップに張りつけておくのもよいかと思いますが、いかがでしょうか。","respondent":"大澤広報広聴課長","answer":"区として区民の方に見てほしいという思いがそれぞれあって、所管でも、それぞれ全て、そういう思いで作られていると思いますので、何を基準にして優先順位をどのようにつけるかということは大きな課題となると思いますが、出し方については検討してまいりたいと思います。","voiceIndex":116,"id":"exchange-049"},{"speaker":"湯澤委員","kind":"質問","question":"ＹｏｕＴｕｂｅは、テレビと違って有名人でなくても、共感できる一般の方で人気が出ているというのが特徴であると思いますので、その特徴を活かして、例えば子どものレポーターが大人に鋭い質問を投げかけるとか、ご高齢のレポーターが若者に対して世代を超えて質問を投げかける。さらにはその双方が担当課長や区長といったところに直接聞いてみたというような企画。","respondent":"大澤広報広聴課長","answer":"なかなか今、区民レポーターの方の活用というのが難しい状況ではありますが、再開の際には、委員のご提案も含めて検討してまいりたいと考えます。","voiceIndex":118,"id":"exchange-050"},{"speaker":"湯澤委員","kind":"質問・要望","question":"品川区の公式ＬＩＮＥについてもお伺いします。やはり目標値というのが必要だと考えています。２万人というのは大変多い人数だと考えていますが、今後、区民の１割を目指すとか、万が一に備えて、できる限りの区民に登録してほしいと考えておりますが、今後の目標などもあれば教えていただきたいと思います。","respondent":"大澤広報広聴課長","answer":"ＬＩＮＥの登録数につきましては、かつて登録数が多いと言われていた区を目標としていましたが、その目標についてはクリアできました。次の目標としては、よく言われている、人口の１割ということで、今の倍の４万人を目標に取り組んでまいりたいと考えております。","voiceIndex":120,"id":"exchange-051"},{"speaker":"湯澤委員","kind":"確認","question":"続きまして、１７３ページの成人式経費に移ります。そこで伺いたいのですけれども、来年度、成人となる方に対して、いつどのように成人式があるということをお伝えするのか。当事者には、気になって区のホームページなどを見て確認した人もいるかもしれないですけれども、区民にも、広報紙などを活用して、早い時期に発信していくべきではないかと思いますが、いかがでしょうか。","respondent":"古巻総務課長","answer":"ちょっと言い間違えられたのかと思うのですけれども、基本的には、昨年度になると思いますけれども、成人年齢の引下げが分かった時点で、年齢については検討させていただきまして、成人式という名称にするかどうかはこれからの検討になりますけれども。","voiceIndex":122,"id":"exchange-052"},{"speaker":"湯澤委員","kind":"質問","question":"大変失礼しました。二十歳であります。今後も、一生に１度の成人式でありますので、また成人年齢が引き下げられたことにより、犯罪や詐欺に巻き込まれない、そういった区からのメッセージも一緒に、対象者全員の記念品を準備して、成人式当日に来られなくても、例えばはがきとか、そういったもので、本人ではなくても交換ができるといった取組みも検討すべきではないかと思いますが、いかがでしょうか。","respondent":"古巻総務課長","answer":"記念品につきましては、会場にいらした方をというようなことで、今年度につきましては、またちょっと違う取扱いをしていますけれども、今後も例えばオンラインを併用するなどという形が続く可能性もありますし、様々に検討させていただいて。","voiceIndex":124,"id":"exchange-053"},{"speaker":"湯澤委員","kind":"質問","question":"品川区で育った成人の皆さんの門出でありますので、区が心を込めて祝ってあげる。そういった成人式になりますことを希望いたしまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-054"},{"speaker":"つる委員","kind":"提案","question":"１７３ページ、非核平和都市品川宣言事業、それから１７３ページ、国際交流推進事業、１８９ページ、児童見守りシステム運営費について、伺っていきたいと思います。そのような思いも込めて、平和の種、平和の種子の事業の提案をさせていただいて、品川区として、平和の種子、種を配布していただく事業をやっていただいているところには感謝しているところであります。要は、種をまき続ける。","respondent":"古巻総務課長","answer":"すぐに何ができるということではございませんけれども、ご指摘を受けまして、何か工夫していけることはないだろうかということは検討してまいりたいと考えております。","voiceIndex":128,"id":"exchange-055"},{"speaker":"つる委員","kind":"提案","question":"ただ一方で、しながわ平和の花壇としては、区立中学校、それから義務教育学校の計１５校に、花壇というのを設置していただいていて、それは荏原地域にも八潮地域の中にも、学校の中でということを含めれば、それはあるわけでありますけれども、より一層、平和の意識を区民にしっかりと啓発いただくという部分では、今、ご答弁いただきましたが、荏原地域・八潮地域に、新たなそうした意識を確認できるような。","respondent":"古巻総務課長、中元スポーツ推進課長","answer":"ボッチャをはじめ、パラパワーリフティングでありますとか、ホームタウンとしてコロンビアの方々、選手をお迎えしておりますので、大使館を含め、スポーツ推進課を含め、庁内連携を致しまして、そういった形での催しといいましょうか。ボッチャにつきましては、やはり区民の方が公募を通して広く参加できる大会を今後検討してまいりたいと考えておりますので、総務課とも連携させていただいて、先方との調整が整いましたら。","voiceIndex":130,"id":"exchange-056"},{"speaker":"つる委員","kind":"質問・要望","question":"次は児童見守りシステム運営費、まもるっちですが、本来であれば、令和３年度中に令和５年度の新たなシステム改築に向けての検討がされるはずでしたが、これは事前に伺った中では１年延びたということで、いろいろなご意見を反映させていくというところを伺いました。ここについては、あくまでも第一義には、しっかりと児童の命を守る。ここは期待で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-057"},{"speaker":"おくの委員","kind":"質問・要望","question":"建物に溶け込んで、目を凝らして見ないと分からないようなものが現在の表示でありまして、そうではなくて、言わば建物から別個独立して浮き上がって見えるような、誰の目にも一発で、ここが地域センターだと分かるような表示が欲しいというのが、私が幾人かの方から伺ったご要望なのです。そういう表示をしていただきたいのですが、その点、いかがでしょうか。この２点をお伺いしたいと思います。","respondent":"川島地域活動課長","answer":"ただ、３月中ぐらいに設置ということなので、できるだけ早く表示をしていただけるようにお願いしまして、区民の方の利便性向上を図っていきたいと思ってあります。","voiceIndex":135,"id":"exchange-058"},{"speaker":"おくの委員","kind":"質問・要望","question":"水を入れて設置するような看板を設置していただきたいと思います。それから駅前のことですけれども、駅の中ではなくてもいいのです。地上に出て、道路の上に、こちらの方向に行くと地域センターがあるのだという、道路上でも構わないと思います。だから、そこのところを、大きめのきちんと目立つものにしていただければいいと思うのですけれども、そこを考えていただきたいのですが、いかがでしょうか。","respondent":"川島地域活動課長","answer":"古い表示もあるということですので、再度点検いたしまして、どんな工夫ができるか、何ができるかというところを再度点検していきたいと考えています。","voiceIndex":137,"id":"exchange-059"},{"speaker":"おくの委員","kind":"質問・要望","question":"何とか工夫はできると思いますので、どうぞよろしくお願いいたします。荏原第一地域センターの利用者は、センターの下の１階にある駐輪場の特定の区画が無料で利用できるようになっています。周知を徹底させていただきたいと思います。地域センターの入り口近くの内側と外側にも大きくその旨を表示したらどうかと思いますが、まずこの点がいかがかということ。この２点、いかがでしょうか。","respondent":"川島地域活動課長","answer":"こちらの駐輪場につきましても、移転当初から、地域センターでも駐輪場が無料というのが分かりにくいということは認識しておりましたので、手作りの案内札を置いたり、案内表示はしていたということですけれども、それでも分かりづらいです。","voiceIndex":139,"id":"exchange-060"},{"speaker":"おくの委員","kind":"質問","question":"これも先ほどと同じで、非常に大きくしてもらわないと、せっかく１２台も用意しながら、この区画がそうだと分からないということです。本当に、Ａ４やＡ３の紙１枚では分からないということですので、よろしくお願いいたします。それから３点目、もう一つ伺います。なぜ新しい荏原第一地域センターでは放送設備などが有料になり、また利用料も値上げになったのでしょうか。この点を伺います。","respondent":"川島地域活動課長","answer":"そうしますと、こちらは例えば第１集会室ですと料金は変更ないですし、それから第２集会室、第３集会室も、それぞれ１００円高くなったところと安くなったところがありますので、多分、備品の料金が１回有料になったというようなご指摘だと思います。","voiceIndex":141,"id":"exchange-061"},{"speaker":"おくの委員","kind":"質問・要望","question":"値上げは、設備が新しくなっても、今までは無料で、要するに部屋の利用料を払えばそれに附帯する設備として使えていたものが、お金を払わないと使えなくなるわけです。なるべく利用しやすいようにしていただきたいのですけれども、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-062"},{"speaker":"大沢委員","kind":"質問・要望","question":"１８９ページ、青少年健全育成事業、それと１８３ページ、地域課題の解決支援、それと時間がありましたら、１６９ページ、品川区民憲章について伺いたいと思います。そこのところの事情、周辺の状態を教えていただきたい。","respondent":"川島地域活動課長","answer":"第２１回中学生の主張大会の実施の工夫ですが、マスク着用など基本的な感染防止対策はしっかり行いまして、式典のタイムテーブルを見直して時間短縮を図ったほか、参加者の人数も最低限度に絞らせていただきました。","voiceIndex":145,"id":"exchange-063"},{"speaker":"大沢委員","kind":"質問・要望","question":"それで、ここのところ、たまたま今、中学生の主張大会ということで伺いましたけれども、１３の地域センターがあるわけで、その地域活動の中で、コロナ禍における地域活動は、どのような工夫をされて様々な事業を仕掛けていっていらっしゃるのか、そこの現状をお知らせいただきたいと思います。","respondent":"川島地域活動課長","answer":"来場者も５５０人ほどということで大変好評で、コロナ禍の中でも、お子さんたち、来場者の方は皆さん楽しんでいかれたということで、実施できてよかったと考えているところです。","voiceIndex":147,"id":"exchange-064"},{"speaker":"大沢委員","kind":"質問・要望","question":"これはいいことだと思います。この中で、１８３ページですけれども、プレス発表を見ていまして、町会、地域課題の解決支援についてということで、ここのところ、テーマ別意見交換会と課題解決支援業務についてお伺いするのですけれども、外部コンサルタント等を町会に派遣し、伴走型とありますけれども、この伴走型および、この内容について、もう少し詳しくお答えいただきたい。","respondent":"川島地域活動課長","answer":"こちらは、テーマ別懇談会の開催と併せまして、コンサルタント会社に業務委託をするような予定で、今、準備を進めております。","voiceIndex":149,"id":"exchange-065"},{"speaker":"大沢委員","kind":"質問・要望","question":"それと、次の質問ですけれども、先ほど、荏原第一地域センターが新しく移ってきたわけですけれども、去年の７月からということでありますが、その後、何か変わった事情、特に何か変わったことがあった、あるいは何か出来事があった、それについて状況や変化があったら教えてください。","respondent":"川島地域活動課長","answer":"日曜開庁、それからマイナンバーカード交付ともに、新たに始めた部分は大変好評で、平日の窓口の取扱い件数で言いますと、いろいろな件数があるのですが、移転前の取扱い件数から比べますと、１.２倍から１.３倍程度の発行件数となっておりますので、大変、使っていただいて。","voiceIndex":151,"id":"exchange-066"},{"speaker":"大沢委員","kind":"質問・要望","question":"ましてやコロナ禍で地域の結びつきが、人と人との結びつきが弱くなっているところ、この５つの基本線をしっかりと押さえながら、今後、行政、政治を行っていく必要があると思うのですけれども、シティプロモーション、広報広聴課と、これは企画部になるのでしょうか、そこのところは分からないですけれども、その辺の関係を教えていただきたいと思います。","respondent":"大澤広報広聴課長","answer":"これは、シティプロモーションが目指す、区民の皆様に、区への愛着と誇りを深めて住み続けていただきたいという思いと一致するということで、現在はシティプロモーションで普及啓発を図っております。","voiceIndex":153,"id":"exchange-067"},{"speaker":"大沢委員","kind":"質問・要望","question":"憲章であるから、本当に皆さん方に、ちなみによく、区の行事のときに皆で唱和、皆で読み上げるわけですし、そこの部分は普及啓発があるとは思うのですけれども、この施策、方向性、政策については、やはり広報広聴課のみならず、別の部署でもしっかりと押さえて運んでいく必要性があると思うのですけれども、私も頑固なもので譲らないかもしれないですけれども。","respondent":"佐藤企画調整課長","answer":"来年度の予算で、区民憲章の周知もお願いしていますが、委員ご指摘の観点も踏まえて、総合実施計画でもそのようなバランスを捉えた事業展開を、全庁一体となって進めていきたいと考えています。","voiceIndex":155,"id":"exchange-068"},{"speaker":"大沢委員","kind":"質問・要望","question":"ぜひとも、ここのところは、松本委員がいる前で誠に僣越ではありますけれども、憲法に根差すものでして、これは動かせないものであるので、そこのところはしっかりと押さえながらやっていただきたいし、広報するだけで終わりでは、終わってはいないでしょうけれども、しっかりと、ここのところを検証しながら、私たちは読み上げて終わってしまう部分が、自分自身もよくありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-069"},{"speaker":"小芝委員","kind":"提案","question":"私からは、１８５ページ、町会・自治会ＩＣＴ活用促進補助と、同じページの児童参加地域事業補助について、お伺いいたします。これまで、昨年の予算特別委員会で、町会や自治会の会館へのインターネット環境の整備に向けた提案などをさせていただきました。今回の予算を見ますと５００万円が計上されております。この予算規模にしました理由、また経緯について教えてください。","respondent":"川島地域活動課長","answer":"ＩＣＴ活用促進補助の５０町会の根拠ということですが、こちらは、令和２年度に新設しました新型コロナウイルス感染症対策物品補助金の執行実績が、五十数件だったということから、それを参考にしまして５０町会分を、まず予算計上しました。","voiceIndex":159,"id":"exchange-070"},{"speaker":"小芝委員","kind":"質問・要望","question":"利便性を追求するには、それぞれの町会・自治会の自助努力によることも大きいと思いますが、例えばＩＣＴに長けた職員による相談対応などを行っていただきたいと考えますが、いかがでしょうか。民間コンサルタントを活用しました場合も、この促進費に当てはまると聞いておりますが、その紹介も含めて、品川区からアプローチしていただきたいと考えますが、いかがでしょうか。","respondent":"川島地域活動課長","answer":"そちらをどのように活用していくかということで、例えば地域センターの職員が講師になって、タブレット教室を開いたりしておりますので、区の職員が対応できるようなご相談にも、当然、地域センターでは乗っていくと思いますし、それから。","voiceIndex":161,"id":"exchange-071"},{"speaker":"小芝委員","kind":"質問","question":"区のバックアップがありましたら大きな後押しになりますし、町会・自治会の活力にもつながると考えますので、よろしくお願いいたします。続きまして、児童参加地域事業補助について伺います。子どもが行事に参加すれば、その効果というのは親にも波及し、その親を町会に引き寄せる効果があると認識しておりますが、その辺りの考えを教えていただけますでしょうか。","respondent":"川島地域活動課長","answer":"今、委員がご指摘されたとおり、町会・自治会の役員の方も同じような感想を述べられる方が多くて、子どもが参加するイベントをうまく打てるようになれば、親御さんも一緒に来ていただけるということで、そういったところが、何か将来の役員になるような、候補の方に声をかけたり。","voiceIndex":163,"id":"exchange-072"},{"speaker":"小芝委員","kind":"質問","question":"先ほどのＩＣＴ活用促進補助と連携しました、オンライン特化の行事、または対面とオンラインのハイブリッド型の行事といったものを含めて、先ほど私が地域の例として提示しました、町会や自治会の様々な事例を区からも町会などに提示してもらうことで、より一層、また今度は町会・自治会の活性化につながると考えますが、いかがでしょうか。","respondent":"川島地域活動課長","answer":"町会・自治会の先進事例というか、紹介ということになりますと、３月中に町会・自治会活動の事例集を発行する予定です。","voiceIndex":165,"id":"exchange-073"},{"speaker":"小芝委員","kind":"提案","question":"ぜひそういった先進事例の案内・提示を前に進めていってもらいたいと考えます。どうしても、現役世代の参加や、また提案がないと、これまでどおりの従来型の行事に固執してしまっているといいますか、その枠からなかなか飛び出せないようなところも、やはり現状としてあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":167,"id":"exchange-074"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、１７７ページ、ＤＶ・カウンセリング相談、１８５ページ、町会・自治会加入促進支援、２０７ページ、マイナンバーカード普及促進の３点についてお伺いします。そこで、品川区の現状はどのような状況でしょうか。併せて、事業者、相談事業について区民の方から何かお声が入っておりましたら、その点をお聞かせいただきたいのと、あと区としてこの事業の評価をお聞かせください。","respondent":"島袋人権啓発課長","answer":"順不同になりますが、総合相談の中におけるＤＶ相談に関して、お答えいたします。委託先ですが、全国女性シェルターネットというＮＰＯ法人にお願いしています。","voiceIndex":169,"id":"exchange-075"},{"speaker":"こんの委員","kind":"質問","question":"多様化する相談が増加する傾向にありますので、この相談の充実が必要だと考えるわけですが、なぜこのような体制であるかというところの経緯をお聞きしたいのと、今、微増というか、昨年とあまり変わらないということでしたけれども、でもやはり高い数字だと思うと、この日にちには合わなくて、相談をためらうというか、断念してしまうというケースも中にはあるのではないかと思うのですが。","respondent":"島袋人権啓発課長","answer":"男性の相談も含めながら、カウンセリング相談・ＤＶ相談を増やしていきたいと考えているところですが、なかなか時間的にも難しい部分がありますので、東京都ウィメンズプラザを紹介したり、させていただいたりしています。","voiceIndex":171,"id":"exchange-076"},{"speaker":"こんの委員","kind":"質問・要望","question":"実態はどのようになっているのか、品川区としては委託ですから、その点どのような状況なのかもお聞かせいただきたいと思います。それに対して必要な対策を見いだしていく。こうしたスキルも求められていくところであります。体制をつくっていただきたいのですが、また委託業者へ相談員のスキルアップや処遇改善をお願いしたい。こうしたことも要望するわけですが、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"男女共同参画センターで行っておりますＤＶ相談ですが、まずはどういったことかということからお話ししますと、これはＤＶかどうかというところの確認の、入り口の相談に対応していますので、その入り口からもう少し深いところに入りますと、すぐにしかるべき支援先を紹介して。","voiceIndex":173,"id":"exchange-077"},{"speaker":"こんの委員","kind":"質問・要望","question":"その辺のところをどうかご理解いただいて、対応が難しい案件もあるとは思いますが、寄り添った対応をお願いしたいという要望で、この質問をさせていただいたところです。お願いいたします。次に、マイナンバーカード普及促進について伺いたいと思います。こちらは、申請の補助を来年度、タブレットを活用して行ってくださるということで、大変ありがたい事業だと考えています。","respondent":"木村戸籍住民課長","answer":"当初はまず、区役所の特設会場で受付を行うような体制を考えておりまして、もちろん日曜日も行います。それから、端末を持ってこられている方についても支援ということで、ご案内をさせていただこうと考えています。","voiceIndex":175,"id":"exchange-078"},{"speaker":"こんの委員","kind":"質問・要望","question":"持っている方でも持っていない方でも対応してくださる。それで、申請をお手伝いしていただいて、現地で申請した後、交付時の取扱いについて伺いたいのですけれども、そうなると、その端末で申請に来られているので、対面で、その場でご本人の確認ができると思うのです。そうしたことをしていただきたいと思う。今はそうなっていないと思うのですけれども、いかがでしょうか。","respondent":"木村戸籍住民課長","answer":"ですので、郵送の部分で少し課題がありますけれども、引き続きこれは検討させていただきたいと思います。","voiceIndex":177,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"非常にクレームが多くて、移設をしていただけないかということでありますが、そのお考えはありますでしょうかということです。それから、１９５ページのきゅりあんですが、１年間、大規模改修という形になっているのですけれども、大分施設も古くなって、設備が古くなっていると思って確認したいのですが、プロジェクターは常備されますか。空いていれば貸してあげればいいじゃないですか。","respondent":"森田生活安全担当課長、篠田文化観光課長、黒田財政課長","answer":"いずれにしましても、先ほどと同じ話になってしまいますけれども、受動喫煙に配慮した何かしらの対策ができないかということで。コロナ対応の各種物品等の設置ですけれども、こちらは今も様々、工夫はしているのですけれども、必要な点については、ご指摘の点も踏まえながら。基金の、まず予算の立て方ですが、今回の令和４年度の当初予算につきましては、基本的には基金を預けている利子があれば。","voiceIndex":181,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"喫煙所は、あそこは交通が非常に激しい通りで、人がたくさん通るわけです。クレームが非常に多いのです。非常にクレームが多いです。ただ、通常の会議がありますよね。要は、長期にわたっての計画があって、基金というのがあるのではないのですかという。その顔に対して、やはり人事課の中で、きっちりと指導し、調査し、研修などをしていくというのも必要ではないかと思うのですが、いかがでしょうか。","respondent":"黒田財政課長、篠田文化観光課長","answer":"基金のところですが、今年度、総合実施計画を策定する中で、投資的経費が各年度でどのぐらいかかりそうかとか、工事がこの辺でありそうだというところは、当然、計画の中で見ていきまして、それを積み上げて。実際に、こういった施設の窓口等のマナー等あるいは引継ぎの問題につきましては、異論のないように、例えば事業者が変わる場合には、きちんとした指導はしているのですけれども、そういった点も見受けられるということであれば、今後。","voiceIndex":185,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"私は、そこは人事課でしっかり見ていく必要があるのではないかと思うのですが、人事課としての考え方をお聞きしたい。","respondent":"崎村人事課長","answer":"今、文化観光課長が申し上げましたけれども、職員の部分については接遇研修等々、新人研修の中でもメニュー化してやっているところではありますけれども、各種窓口、特に委託の部分につきましては、そこの所管と委託会社の中で。","voiceIndex":188,"id":"exchange-082"},{"speaker":"西本委員","kind":"意見","question":"いずれにしても品川区の顔になりますので、委託であろうと何であろうと区民には変わりません。同じ対応を致しますので、それぞれの所管がしっかり指導していただきますようお願いして終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":190,"id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１６７ページから、各課に記載されている会計年度任用職員の待遇改善について、１７３ページ、非核平和都市品川宣言事業に関わって、ロシアのウクライナ侵略について伺います。ロシア軍の即時撤退を求める決議が全会一致で可決されたことは画期的です。品川区としても、この抗議声明を出すべきですが、朝の質疑で、ロシアの軍事侵攻について何らかの意思表示を検討しているという答弁がありました。","respondent":"古巻総務課長","answer":"それで、今回のロシアによるウクライナへの武力侵攻に関しましては、区としても憂慮していたところですが、国連での決議があり、また様々な状況を鑑みまして、区としても、そういったことに対しては遺憾の意を表明するべきだろうということで、今。","voiceIndex":192,"id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"そのためにも、国際連合憲章に違反しており、非核平和都市品川宣言にも反するという立場に立つことが重要だと思うのですけれども、いかがでしょうか。","respondent":"古巻総務課長","answer":"何か、食い違っているとは思わないのですけれども、非核平和都市品川宣言の趣旨に則りまして、今回のロシアへの対応については、しっかりと対応していきたいと考えております。","voiceIndex":194,"id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"遺憾の意を示していきたいというところは、ぜひやっていただきたいと思うのですけれども、やはり侵略行為を許さないという立場で、態度表明をしていっていただきたいと思います。２０２０年４月から、会計年度任用職員制度が始まり、２年になろうとしています。区として、どういった仕事内容・職種に会計年度任用職員を適用しているのか。区内の会計年度任用職員の人数と、そのうち女性の人数を伺います。","respondent":"崎村人事課長","answer":"人数につきましては、時期によりまして若干、上下するところではあるのですけれども、大体１,３５０人ほどに、会計年度任用職員として従事いただいているところでございまして、中でも女性の方は１,１５０名ほどいらっしゃいます。","voiceIndex":196,"id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"単年度契約なので、４月からの計算になっていて、手当が満額出ていないという声を頂いたのですが、これが本当かどうか、そこを伺いたいと思います。１年ごとに履歴書を逐一出さないといけないということで、そういったところも、前年度に勤務していた方は、省略するなど、簡略化していくことができないか、伺います。","respondent":"崎村人事課長","answer":"会計年度任用職員につきましては、委員もご存じのように、会計年度という冠がついているように、その会計年度ごとに職を設置することの必要性を検証しまして、新たに職を設置して公募によって選考を実施しています。中には引き続き応募いただいて採用になる方もいらっしゃいます。","voiceIndex":198,"id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"いかがでしょうか。私がお話を聞いた方は３０年近く続けられているということですけれども、そういった方でも給料が上がらないということで、ぜひ昇給制度をつくっていただきたいと思うのですけれども、いかがでしょうか。実際に、港区や杉並区、荒川区ではやっているということを聞いておりますので、他区の取組みでつかんでいるところがあればご説明いただきたいと思います。","respondent":"崎村人事課長","answer":"ですので、区としても、その考え方に基づいて、先ほどもお話ししましたように、職の必要性を吟味した上で、毎年度、採用選考を実施しています。","voiceIndex":200,"id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすれば仕事の効率なども上がっていくということで、ぜひここは昇級制度を考えていただきたいと思いますし、また休暇の面で、正規職員と会計年度任用職員に違いがあります。その違い、会計年度任用職員が無給休暇となっているところを改善していただきたいと思うのですが、何があるのか、伺います。","respondent":"崎村人事課長","answer":"休暇については、確かに無給となっている部分がありますけれども、今回、出産・育児の部分では有給化するところなどもありますので、今後も引き続き対応してまいります。","voiceIndex":202,"id":"exchange-089"},{"speaker":"西村委員","kind":"質問","question":"生涯学習推進事業より、しながわ学びの杜、障害者スポーツの充実、時間が許せば広報広聴費について伺ってまいります。しながわ学びの杜の新規取組について伺ってまいります。次年度、知的障害がある方向けに、アートをテーマにした講座が新設されます。この講座がどのような内容になるのか、伺います。","respondent":"篠田文化観光課長","answer":"今、委員からお話があったとおり、アートを中心としたということで、今回、天王洲が「アートの街」ということでもありますので、そういった資源も活用しながら、講師の方も臨床美術士という資格をお持ちの、これは国家資格ではなく団体資格ではあるのですけれども。","voiceIndex":205,"id":"exchange-090"},{"speaker":"西村委員","kind":"質問・要望","question":"大変楽しみな講座になると考えています。我々の会派で２年前に視察に伺った、御殿場の障害者支援施設があります。障害をお持ちの方々が働きながら、日中活動として、音楽、和太鼓、絵画、造形、陶芸などを楽しんでおられました。今後、様々な障害をお持ちの方への講座の広がりをご検討いただきたいと思いますが、区のお考えをお聞かせください。","respondent":"篠田文化観光課長","answer":"ただ、今後、やはりその辺について、様々展開をしていく方向性というのを見据えながら、今回、実施してまいりたいと考えているところです。","voiceIndex":207,"id":"exchange-091"},{"speaker":"西村委員","kind":"提案","question":"ちょっと私の質問の仕方が悪かったのですけれども、様々な障害をお持ちの方の講座の広がりというのをご提案させていただきたいと思っておりまして、例えば聴覚障害をお持ちの方が、この間、区内の教室で、健常者の方と一緒に、己書というデザイン書道を楽しんでおられました。申し訳ありません。もう一度ご答弁をお願いいたします。","respondent":"篠田文化観光課長","answer":"私どもも、そういった形でのニーズというのは広く見ているところでもあります。ただ、なかなか一般の方の講座とは違って、困難性が伴うものもあると考えられますので、その辺の課題もしっかり研究しながら、今後対応してまいりたいと考えているところです。","voiceIndex":209,"id":"exchange-092"},{"speaker":"西村委員","kind":"質問・要望","question":"重度の知的障害の方ということでおっしゃっておられますが、安全性の確保、またサポート体制に配慮していただきながら、ぜひとも取り組んでいただきたいと考えています。こちらは、ぜひともご検討いただきたいと思いますので、要望します。障害者スポーツに関しましても伺ってまいりたいと思いますが、今、戸越体育館でフリー教室を様々に行っていただいていると思います。","respondent":"中元スポーツ推進課長","answer":"こちらは戸越体育館で、指定管理者の事業として行っております障害者スポーツフリー利用ですが、毎年少しずつメニューが変わりますが、ちょっと戸越体育館の資料が、中身の具体的なものがないのですが、今までですと、ソフトバレーボールやキックベースボール。","voiceIndex":211,"id":"exchange-093"},{"speaker":"西村委員","kind":"質問・要望","question":"いろいろなスポーツ、あといろいろな取組みができるきっかけをぜひとも続けていただきたいと考えています。続きまして、広報広聴費から１点、お伺いします。ささいなことかもしれませんが、こういったところのユーザビリティも求められるようになってきていると感じておりまして、区のお考えと、そのような封筒が今現在あるかどうか、念のため確認させてください。","respondent":"大澤広報広聴課長","answer":"封筒のＱＲコードの不具合というのは、私のほうでは今、確認できていないのですが、そのような事実があれば、ＱＲコードをせっかく印刷しても意味がありませんので、今後、調査等をかけて修正していきたいと思います。","voiceIndex":213,"id":"exchange-094"},{"speaker":"西村委員","kind":"提案","question":"先ほど湯澤委員もおっしゃっていましたが、ＬＩＮＥの活用です。私も充実の提案をさせていただいていますけれども、今後、道路課のアプリなど、アプリがどんどん増えていくことを懸念しております。技術的にＬＩＮＥと同期させるというようなことが難しいのかどうか、専門ではないので分からないのですが、そのように、アプリをＬＩＮＥと同期させていくということが可能なのかどうか、お伺いさせてください。","respondent":"大澤広報広聴課長","answer":"各所管でつくっているアプリと区の公式ＬＩＮＥ、いろいろあるのですが、それの統合というのはなかなか難しいと聞いてあります。","voiceIndex":215,"id":"exchange-095"},{"speaker":"西村委員","kind":"提案","question":"私もすごく難しいと思っておりまして、実際にＬＩＮＥの方にもお話を伺ったりしております。個人情報の問題などといったこともあると思いますが、アプリが増えますと、そのアプリそれぞれに、知っていただくという、また周知の努力が必要になってきますので、何かいいアイデアと工夫を私も考えまして、またご提案させていただきたいと思います。引き続きよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":217,"id":"exchange-096"},{"speaker":"渡部委員","kind":"質問・要望","question":"２１０ページの統計調査費のところと、１６９ページの広報広聴費、１７１ページの情報化推進費の関係を、時間内で聞いていきます。そして、どういうものがどれぐらい。大体どういう調査を、この４万円か何かで調査がかかってくるのか。それで、今年は就業構造基本調査というものが入っているのだけれど、そもそもこれはどういうもので、何のためにやっているのか、その辺をご説明いただきたいと思います。","respondent":"川島地域活動課長","answer":"就業構造基本調査につきましては、国の就業・不就業の状態を明らかにし、全国および地域別の就業構造に関する基礎資料を得るということで、こちらも総務省が５年ごとに実施するということで、令和４年調査で１８回目になるものです。","voiceIndex":219,"id":"exchange-097"},{"speaker":"渡部委員","kind":"質問","question":"すみません。失礼しました。ありがとうございました。やはり、国の調査というのはどうしても、ある程度手書きで返していくような仕組みになっているのかどうなのかだけ、分かれば教えてほしい。","respondent":"川島地域活動課長","answer":"多分、調査によってまた方針が変わってくるとは思うのですけれども、経済センサスにおきましても、インターネットや郵送での回答が中心になっておりますので、時代や、そういったものに合わせて変わってきて、やっていただいているという形になると思います。","voiceIndex":221,"id":"exchange-098"},{"speaker":"渡部委員","kind":"質問","question":"すみません。あれ、またどこかケーブルテレビのチャンネルを押してしまったかと思って、直してもう１回見ていたら、もう１回入ったのです。あれは、伺ったらシティプロモーション関係のものが流れているという話なのだけれど、ＹｏｕＴｕｂｅを見ていて、多分、途中で広告が入ると、その広告にいらっとする人が大半だと思うのです。ですから、その辺はどういう仕組みでどうなっていたのか、教えてほしい。","respondent":"大澤広報広聴課長","answer":"ＹｏｕＴｕｂｅですが、令和３年６月１日より、ＹｏｕＴｕｂｅが利用規約を変更しまして、収益のない動画にも広告が出るようになってあります。区としましては、令和３年１０月から、広告としてシティプロモーションの動画を配信しております。","voiceIndex":223,"id":"exchange-099"},{"speaker":"渡部委員","kind":"質問","question":"あれは仕組みとして、５秒は見ないと駄目じゃないですか。その５秒にどんと凝縮して、「わ！しながわ」といきなり言って、二、三秒で大事な情報を流して、そこで食いついた人は、あと１０秒見るとか、そのようなつくり方も、逆にもう、それがどうせ出てしまうのだったら逆手に取って。ワクチン接種は何月何日までとか、そういう大事な情報がぱっと入るような仕組みがいいと思うのですけれど、どうでしょうか。","respondent":"大澤広報広聴課長","answer":"ＹｏｕＴｕｂｅの広告の配信は始めたばかりですので、今後どのような活用の仕方があるのか研究してまいりたいと考えております。","voiceIndex":225,"id":"exchange-100"},{"speaker":"渡部委員","kind":"確認","question":"もうやめますけれど、勝負は５秒ですから。もう一件、広報広聴費のところで確認したかったのが、デジタルサイネージというものが出だして、ただ、何か新しいコンテンツが出たりという感じではないのですけれども、この予算書に出ている費用というのは、いわゆる、区役所の中に置いてあるやつとか地域センターに置いてあるやつとか、そういうものの経費でしたっけ。この内訳の確認をさせてください。","respondent":"大澤広報広聴課長","answer":"デジタルサイネージの利用料ですけれども、現在、区内に２９台ありますので、そのリース料となっています。","voiceIndex":227,"id":"exchange-101"},{"speaker":"渡部委員","kind":"質問","question":"その地域の方々とやり取り、要するに地域の方々に運営を任せたりして、そのまちの、例えば商業の宣伝やイベントの宣伝なども入れられるような仕組みなど、どんどん、まちの活性化に使えればいいのになどと、ずっと思っているのですけれども、その辺は少しずつ進歩しているのでしょうか。","respondent":"大澤広報広聴課長","answer":"デジタルサイネージですけれども、年度を追って設置しておりますが、最初に設置したものが、来年度ちょうどリース満了を迎えますので、その後どうするかということは、今後検討ということになるかと思いますけれども、今、大分、性能自体が上がっていて。","voiceIndex":229,"id":"exchange-102"},{"speaker":"渡部委員","kind":"質問・要望","question":"今、民間の銀行などでも、そのような仕組みで個人的なインターネットバンキングを仕掛けられるようになっていたりするのだけれど、そこにもう一つセキュリティを何か働かせれば、先ほど言った本人確認の部分など、しなくてはいけないのだというのも、マイナンバーカードのおかげで、その辺は全部割愛できると私は思うのだけれど、実際、その辺はどういうふうに捉えていらっしゃるのか、教えてください。","respondent":"堀越企画部長","answer":"産業面におきましても、データを活用した産業という意味での、産業の活性化といいますか、外国と伍していくというような観点で、国でも検討を進めてあります。","voiceIndex":231,"id":"exchange-103"},{"speaker":"渡部委員","kind":"質問","question":"もう答弁を頂いたのでやめますが、マイナンバーカードだけだったら、誰かが持っていって、番号は何番だったっけと教えてしまったら使えてしまうので、それだけではセキュリティは効かない。だけれども、申請などをするときに、何かもう一つかませることによって、今、部長がおっしゃったように、それで全てが解決できる問題だと私は信じていますので、様々活用いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私からは、ページ数は特にないのですが、令和４年度の組織改正について、障害者福祉課の組織編成についてと、それから１７６ページの人事管理費から、保健所職員の労働実態や職員体制について伺いたいと思います。「福祉」の文言を課名からなくすわけですけれども、「福祉」とは何か、区の認識を伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"「福祉」という言葉ですが、施策として大きな単位です、多くの方々の幸せという意味だと認識しておりまして、そういったものを、２課体制として個別具体的により施策を推進するために、名称を区民の方により分かりやすい形で、障害者施策を推進する課、あともう一つは。","voiceIndex":235,"id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多くの人の幸せということでの「福祉」ということで、全くそのとおりだと思います。そして、それに加えて福祉の概念には、人権保障があります。自治体の義務として求められているわけです。それから、品川区は２０２０年度からの長期基本計画の中でも、高齢者福祉も障害者福祉も「福祉」の文言をなくして「環境づくり」に変えました。この一連の流れではないのか、改めて伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"そういったところで今回、先ほどご説明したとおり、２課体制として、より積極的に、効率的に、施策を推進していくという趣旨です。","voiceIndex":237,"id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、支援というのはほんの一部の、国が国民の権利として保障するのではなくて、支援するというところでは、もう根本から考え方として違ってしまいますので、「福祉」という言葉には当事者・家族の闘いの歴史が込められていますし、品川区は人権保障の立場に立って、「障害者福祉」の文言を変えないよう、改めて求めたいと思いますが、そのことについても伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"来年４月からは、障害者施策推進課と障害者支援課で進めていきたいと考えております。","voiceIndex":239,"id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは、ここだけで終わるものではないので、本当に人権保障という立場に、ぜひとも立っていただきたいということで求めておきたいと思います。次に、保健所職員の残業や職員体制について伺いたいと思います。第６波の１月・２月の残業実態をお聞きしたいと思います。平均残業時間と最大の残業時間はそれぞれ何時間なのか、伺いたいと思います。","respondent":"崎村人事課長","answer":"保健予防課の職員の１月の超勤時間ということでお話をさせていただければと思いますけれども、コロナ対応に当たりました保健予防課の職員の中で、残業が月８０時間を超えていた職員というのは、保健師につきましては８人中６人。","voiceIndex":241,"id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は以前から、保健師がもともと足りないということを、増やしていただきたいということで、ずっと要望し続けてきましたけれども、昨年１０月の決算特別委員会の総括質疑で私が聞いたときに、総務部長は、品川区の保健師数は人口対比で２３区中２２位で、下から２番目という少なさで、平均までに１２人足りないと。なぜ７名採用できなかったのか。その方針はあるのかについて伺いたいと思います。","respondent":"崎村人事課長","answer":"来年度の採用として当初７名を採用予定としていたところですけれども、今現在５名、採用予定です。","voiceIndex":243,"id":"exchange-109"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"厚生労働省が２０２０年３月に、自治体保健師の人材確保ガイドを出しているのです。私はこれを見て改めて、本当に人材を確保するのが大変なのだと。そして、保健師の業務というのは拡大の一途だと。しかも、退職者数は１０年前の１.５倍に増えているという中で、改めて保健師の人材確保策をつくることが必要ではないかと思うのですが、いかがでしょう。","respondent":"崎村人事課長","answer":"区として人材確保策といいますと、保健師については特別区の採用選考になりますので、なかなか確保策を策定するというのは難しいかと思います。","voiceIndex":245,"id":"exchange-110"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１７９ページ、人事管理費の中の、代替職員の雇用制度についてお伺いします。２０１９年の予算特別委員会・決算特別委員会で、人材派遣制度に係る３年制度、いわゆる３年制限の取扱いについて質問させていただきました。このとき、過半数の意思が必要という話でお尋ねしたのですが、根拠を示していただけず残念でした。検討の結果はどのような結論になったのか、教えていただきたいと思います。","respondent":"崎村人事課長","answer":"区では当初、職員団体を想定しておったところですけれども、職員労働組合に照会しましたところ、過半数の職員を抱える団体ではないといったところのご回答を頂きましたので、区では、まず職場代表といったことで、課の出先施設ごとに１名ずつ選出していただきまして。","voiceIndex":249,"id":"exchange-111"},{"speaker":"高橋（し）委員","kind":"質問","question":"お話をされた労働組合が過半数ではないということで、今お話があったように、少し細かいところがあれだったのですが、各職場の代表と区分代表、ここのところは、もう一度お願いします。これは、要するに代表を決めて、その方が選挙等で、あるいは中の話合いですか、選ばれて、その方が代表で出て、今お話のあったような協議をするという仕組みになっているということでよろしいのでしょうか。","respondent":"崎村人事課長","answer":"職場代表といいますのが、課や、また保育園や児童センターなどの出先施設ごとに、まず１名、職場代表というのをご選出いただきまして、さらにその各部の中から区分代表、また保育園であれば保育園の代表といったところで区分代表を選出して、意見聴取を実施したという内容です。","voiceIndex":251,"id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、今ありました令和６年９月まではその体制で、今、契約が、協議が済んだということですね。そうすると、現状はそういった形になっているわけですけれども、また３年経てば同じようなことが、期限がやってきます。そのときに向けて、どのような対応、現在、協議したばかりですけれども、３年後についてはどのような見通しがあるのでしょうか。","respondent":"崎村人事課長","answer":"こちらは、今度３年間、延長になったときに、今度は令和５年度中にこういった手続きが必要になってくると認識しております。","voiceIndex":253,"id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"派遣労働者の方々は、区全体で１３４名の方々がおられると伺っています。労働組合の存在も否定しているものではないという観点で、今、質問させていただきました。法に則って、派遣労働者の方々の労働環境整備に今後も努めていっていただきたいと思います。これは、年度末に策定すると伺っていますが、現状、令和４年度の計画はもう策定されたのでしょうか。","respondent":"今井監査委員事務局長","answer":"監査基準に基づく監査計画ですが、毎年度、翌年度の計画につきましては、大体３月までに策定するという形になっております。現時点ではまだ策定はしていない状況です。","voiceIndex":255,"id":"exchange-114"},{"speaker":"高橋（し）委員","kind":"提案","question":"品川区では、監査計画、今、３月にというお話がありましたが、行政監査や財政援助団体等の監査など、議員選出監査委員の方が、問題意識を持って能動的に、こういう監査という提案をすることが行われていると思います。私は監査の中身が分かりませんので、その機会というのは、どのような場であるのでしょうか。","respondent":"今井監査委員事務局長","answer":"監査委員の皆様におきましては、監査計画に基づきまして、細かい内容につきましても、それぞれの監査について監査委員協議会の中でご決定いただきまして、監査を実施していただいているところです。","voiceIndex":257,"id":"exchange-115"},{"speaker":"高橋（し）委員","kind":"提案","question":"ぜひ、その提案等を活かす形で計画を立てていっていただきたいと思います。それで、その計画ですが、２３区のうち半分以上の区が、ホームページで、監査方針、監査実施計画、年間監査計画書、ある区などでは非常に細かい年間監査計画を公表しています。しかし品川区では、それが昨年度も出ていないのですが、何か公表してはいけないという法律上のルール等があるのでしょうか。","respondent":"今井監査委員事務局長","answer":"監査計画につきましては、地方自治法や監査基準などでも、公開について特に定めはございません。監査委員の皆様が、監査委員協議会の中で決めていかれる内容だと承知しております。","voiceIndex":259,"id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"提案","question":"ということは、監査委員の方々が、監査委員協議会の中で決めて、公表しないという形になっているということでしょうか。ぜひ今後、公表していっていただきたい。区民の方々にとって分かりやすい監査をさらに進めるという点で、お願いしたいのですが、その点についていかがでしょうか。","respondent":"今井監査委員事務局長","answer":"区民に分かりやすいホームページの充実につきましては、これは既に検討を進めております。ただし、監査計画につきましては、今承りました内容につきまして、監査委員にお伝えしてまいるという形になると思います。","voiceIndex":261,"id":"exchange-117"},{"speaker":"若林委員","kind":"質問・要望","question":"１８３ページ、地域振興事業の中で、特にマンション管理組合等実態調査について伺いたいと思います。それから、１００戸以上のマンション管理組合、町会ごとの数というのは既に把握されているのかどうか。具体的な数は、時間がありませんので結構ですが、把握されているかどうか、お聞きしたいと思います。この辺を、すみません、４点ぐらいになりましたけれども、お聞かせいただきたいと思います。","respondent":"川島地域活動課長","answer":"調査結果の活用ですけれども、これは当然、報告書にまとめまして、町会につきましては冊子をお配りするだけではなくて、町会長会議の場で説明もさせていただいて、活用できるようにしていきたいと考えています。","voiceIndex":265,"id":"exchange-118"},{"speaker":"若林委員","kind":"質問・要望","question":"１００戸以上ということで取りあえず始められるということで、分かっている部分も多々あると思いますけれども、当然、しっかり確認、またその後の町会へのフィードバック等、町会支援・自治会支援をよろしくお願いしたいと思います。一般質問でも紹介しましたが、まちづくりの部門に確認したところ、いわゆる区分所有マンションが７万数千棟あるのです。","respondent":"川島地域活動課長","answer":"１割ぐらいが区内在住の方かと。それで、近隣の区にお住まいの方がかなりいらっしゃる。もう少し遠いところは、もっといらっしゃるのですけれども。それで、大体、大田区の方が多いのかなという印象が私のほうではあります。","voiceIndex":267,"id":"exchange-119"},{"speaker":"若林委員","kind":"質問・要望","question":"それで、１つだけ。この辺の関連性。企業、協賛団体、それからＬＥＤの数の関連性があるのかどうかというのを教えていただきたいのが１つと、文化観光課としては、私の認識では西五反田二丁目のまちづくりが一定終わって、目黒川左岸を中心にして路上のコインパーキングを撤退させて、歩道を造った工事が終わっていると思います。この辺のご認識はあるかどうか、お聞かせいただきたいと思います。","respondent":"篠田文化観光課長","answer":"今年度の実施に関しまして、ＬＥＤの球数が減ったのと、協賛企業の数が減ったことの関連性ですけれども、企業に関しましては、景気動向等によって様々、それぞれのお考えがあって参加されることと思いますので、そういったことで、この間。","voiceIndex":269,"id":"exchange-120"},{"speaker":"松澤委員","kind":"質問","question":"ＡＩの通話録音機から質問いたします。警察庁によりますと、２０２０年の特殊詐欺の認知件数は前年比の１９.７％減ということで、１万３,５２６件。品川区でも濱野区長より、特殊詐欺の増加における注意喚起がありまして、認知件数が令和２年から令和３年にかけて増加しているとの資料を見ましたが、どうして増加傾向になったのか、最近の全国の動向とともに教えてください。","respondent":"森田生活安全担当課長","answer":"令和３年度になりますと、これは還付金詐欺と言われまして、内容は、ＡＴＭに高齢者の方を誘導して、そこで高齢者の方々に、犯人の口座にお金を振り込ませるというところですけれども、要するにこれは犯人側にとっては、被害者をＡＴＭに行かせてお金を振り込ませるということで。","voiceIndex":272,"id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"詐欺も、コロナ前と、またコロナ後に向けて還付金詐欺と、また詐欺の名目も変わっております。そういった報道が１月にあったと思います。これは実は補助金もなく、品川区独自で始めた事業だと認識しておりますが、この逮捕に至った経緯、そして貸出しの状況、たしか５０件を目標にしていたかと思いますけれども、その辺の状況と、また、普通の自動通話録音機の貸出し状況の現状を教えてください。","respondent":"森田生活安全担当課長","answer":"ＡＩ型自動通話録音機の貸出しの状況につきましては、現在まで１９台ございまして、今年度はあと３台、設置の予定です。","voiceIndex":274,"id":"exchange-122"},{"speaker":"松澤委員","kind":"質問・要望","question":"品川区の生活安全サポート隊というのは、一般職非常勤職員１９人で構成されております。特に青色防犯パトロールカー、通称青パトで、これは特殊詐欺被害防止の注意喚起を行っているものと認識しておりますが、この通称青パトですが、特殊詐欺防止を呼びかけながらパトロールするものですが、活動の体制、そしてまた時間、あとルートが決まっているのか、教えていただきたい。そういうところも教えてください。","respondent":"森田生活安全担当課長","answer":"現在、生活安全サポート隊につきましては、委員のおっしゃるとおり、１９名で対応しています。","voiceIndex":276,"id":"exchange-123"},{"speaker":"松澤委員","kind":"提案","question":"私も６年前に、品川区の自主防犯団体組織というものを立ち上げさせていただきましたが、やはりこの６年間で、ルートの固定化というのですか、飽きてしまっているというのは、正直、私も感じている課題ですので、研究を重ねまして、まず試験的に取り組んでいただいて、固定化する、マンネリ化する防犯システムの一助になるように、また行政全体の効率化に寄与するものと考えますが、ＡＩの導入。","respondent":"森田生活安全担当課長","answer":"先ほどの答弁と少し重なってしまいますが、様々なパトロールのやり方がありまして、私どもでも、朝の登下校のパトロールであるとか、先ほどの繰り返しになってしまうので、またあれですけれども、そういった様々なパトロールの情報を仕入れながら。","voiceIndex":278,"id":"exchange-124"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひ、地域センターで開催されます町会・自治会長会議ですか、多分、今までも月１回やっていると思うのですけれども、そこで新規事業の拡充を町会長に訴えたところで、少し失礼な言い方かもしれないですが、やはり、そういうものを、詳しく分からない人に言っても、全く周知されないのかと個人的に思っていますので、そういったところに、町会長だけではなくて。","respondent":"川島地域活動課長","answer":"町会長会議で説明する際の、若手ですとかパソコンに詳しい方の同席という話です。","voiceIndex":280,"id":"exchange-125"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、国際交流でウクライナ支援を聞かせていただきたいのと、１８９ページの歩行喫煙防止推進経費で、品川区歩行喫煙および吸い殻・空き缶等の投げ捨ての防止に関する条例について伺えればと思います。１６７ページの広報経費で、メールやＳＮＳを通じた区民への情報発信というところを伺えればと思います。","respondent":"古巻総務課長","answer":"ホームページ等でも、そういった形でのご案内をしていると認識しておりますので、引き続き、そちらは日本赤十字社と連携しまして、周知していきたいと考えております。","voiceIndex":283,"id":"exchange-126"},{"speaker":"大倉委員","kind":"質問","question":"ホームページですが、区民の方から寄附先について質問されることが多かったので、このページが、トップページからずっと行った先にあるというところで、ホームページのトップページに、期間を区切って掲載するということもできるのかと思いますので、その辺についてはどのようにお考えでしょうか。教えていただければと思います。では、その点だけお願いします。","respondent":"古巻総務課長","answer":"ホームページは福祉計画課で出しているので、その辺りは連携といいましょうか、福祉計画課とも調整しまして、分かりやすくということも含めて、どういった形でホームページに掲出するかは検討させていただきたいと思います。","voiceIndex":285,"id":"exchange-127"},{"speaker":"大倉委員","kind":"質問・要望","question":"区民のそうした清掃に対して、リスクを背負って、最終的には区が費用を出して行っていくということで、やはり品川区には、歩行喫煙および吸い殻・空き缶等の投げ捨ての防止に関する条例があって、事業者の責務というところ、第５条３項で、「自動販売機の設置または管理を行う事業者は、回収容器を設置し」と書いてありますので。","respondent":"大澤広報広聴課長、森田生活安全担当課長","answer":"それで、今、緊急情報以外は、１週間前には各所管から申請を上げていただけるようにご協力いただいて、あまり短時間で対応しなくて済むように、いろいろ工夫はしています。回収容器の設置です。引き続き、関連団体に対しまして、回収容器の設置などにつきましても周知してまいりたいと考えています。","voiceIndex":287,"id":"exchange-128"},{"speaker":"大倉委員","kind":"質問・要望","question":"午前中のお話の中であった、日本自動販売協会の自販機自主ガイドラインの中には、リサイクルボックスの設置と容器の適正処理ということで、「自販機販売管理者は、リサイクルボックスを、地方自治体の条例に基づくとともに設置先の意向を考慮して」設置することということが書いてありますので、ぜひ連携して、品川区の自動販売機の横に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":290,"id":"exchange-129"},{"speaker":"藤原委員","kind":"質問・要望","question":"１８９ページ、歩行喫煙防止推進経費は空き缶です。私は半年前の決算特別委員会で、自動販売機の数と、自動販売機の横に回収容器が置いてあるかどうか調べてほしいと要望しましたけれども、それはどうなっているでしょうかということと、生活安全推進事業で、わんわんパトロール経費。改めて、わんわんパトロールの目的と、目的が達成されているのかをお伺いします。","respondent":"森田生活安全担当課長、崎村人事課長","answer":"この数について、なかなか把握することは難しいということで、協会のほうからございました。いずれにしましても、自動販売機の横の回収容器の設置などにつきましては、引き続き協会に要請はしてまいりたいと考えています。経験者採用をなぜ実施しているのかといったところですけれども、こちらは民間企業などでの有用な職務経験を有する人材を、幅広く各年代において確保するといったことで。","voiceIndex":292,"id":"exchange-130"},{"speaker":"藤原委員","kind":"質問・要望","question":"でもちゃんと条例は、「吸い殻・空き缶等の投げ捨ての防止に関する条例」と入っているわけですから、項目でも推進経費に「空き缶」と入れていただきたいと思うぐらいの思いで質問しているので、「よく分かりません」とかではなくて、ちゃんと調べて、条例は努力義務かもしれないけれども、ここと、ここと、ここと、ここにはないですよという形でちゃんとやっていかないと、せっかく条例をつくったのに。","respondent":"崎村人事課長、森田生活安全担当課長","answer":"この定年の引上げに関する部分については、６０歳以降の任用ですとか給与退職手当に関する制度について、６０歳を迎える前までに情報提供を行うといったことが法律でも決められておりますので。いずれにしましても、委員が懸念しているようなことにならないように、私どもとしましても対応してまいりたいとは思っております。","voiceIndex":295,"id":"exchange-131"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから半年前に伺いました。伺いましたよね。ここはやはりもう、今日３人の委員が質問しているわけですから、どうしてもやっていただきたいのです。だって、私が回っているだけで、ここもない、ここもない、ここもないと、あるわけですから、もう少しやっていただきたいと思います。定年延長という言葉が出てくるのですけれども、結局は再任用とあまり変わりないと思っていてよろしいのでしょうか。","respondent":"森田生活安全担当課長、崎村人事課長","answer":"各協会につきましては、引き続き要請はしていきたいと考えていますし、いろいろな団体もありますので、私どものほうでも勘案しまして、対応してまいりたいと考えています。再任用と変わらないのかというご質問、なかなか難しいところではあるのですけれども、再任用については、一度、定年退職、退職を迎えてから再度の任用ということになるのですけれども、定年引上げについては、その年齢まで、６１歳。","voiceIndex":298,"id":"exchange-132"},{"speaker":"高橋（伸）委員","kind":"質問","question":"１７３ページ、全国自治体との連携事業、１８９ページ、ＡＩ型特殊詐欺対策アダプタ購入補助等、１９３ページ、荏原地区イベント事業開催経費について、お伺いします。初めに、１７３ページ、全国自治体との連携事業についてお伺いいたします。本年の３月１０日木曜日まで、スクエア荏原で、特別区全国連携プロジェクトパネル展が開催されているかと思います。各区、２３区の交流自治体数が７３２。","respondent":"古巻総務課長","answer":"坂井市との交流ツアーですけれども、坂井市を訪問して交流をというような形で、実際には今年度を含めまして、計画はしていたのですけれども、なかなかコロナ禍という中で実施できなかったということで、予算上はちょっと減額しております。","voiceIndex":302,"id":"exchange-133"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それはもう特別区長会で、これから先いろいろ検討するかと思うのですけれども、今後、交流を考えている自治体とか、マルシェでもいろいろ千葉県の長生村などもやっていますけれども、幾つかお分かりになれば、この先考えている協定というか、交流を結ぶような自治体とかがあるのであれば教えていただきたいと思います。","respondent":"古巻総務課長","answer":"今のところ、具体的にこの先、どことということは、具体的な予定はございませんけれども、全国自治体連携ということで、特別区長会での動きがありますし、また区としても、様々に連携ですとか、協定を結んでいる自治体もあります。","voiceIndex":304,"id":"exchange-134"},{"speaker":"高橋（伸）委員","kind":"確認","question":"ぜひよろしくお願いいたします。続きまして、１８９ページ、ＡＩ型特殊詐欺対策アダプタ購入補助等についてお伺いいたします。先ほど来、松澤委員からも質問がありましたので、重ならないような質問をしたいと思います。先ほどのご答弁だと１９件ということですけども、これは１９件でいいのかどうか、確認だけよろしくお願いします。","respondent":"森田生活安全担当課長","answer":"件数の確認です。区民委員会のご報告のときには１７件でございまして、その後、２月に設置が２件ございました。それで１９件です。","voiceIndex":306,"id":"exchange-135"},{"speaker":"高橋（伸）委員","kind":"意見","question":"分かりました。これは、アポ電で、荏原警察署が令和４年１月に、犯人を逮捕したというのは先ほどもありましたけれども、本当に生活安全担当の課長を含めて職員の方々が、このときはマスコミなど、いろいろ報道があった中で、いろいろ対応が大変だったかと思いますけれども、こういった補助をしていますという部分でいうと、品川区は全国区になって、先進的に取り組んでいることではないかと思っています。","respondent":"森田生活安全担当課長","answer":"１台８,８００円となっておりますので、５０台分で４４万円ということで予算を計上しています。","voiceIndex":310,"id":"exchange-136"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。これは本当にすばらしい取組みだと思いますので、ぜひとも今後ともよろしくお願いします。ありがとうございました。続きまして、新規事業の１９３ページ、荏原地区イベント事業開催経費について、新規事業のまちぐるみ文化イベントについてお伺いいたします。これは１,１００万円という予算額です。それで、これは何月ぐらいを想定しているのかというのをお聞きしたいと思います。","respondent":"篠田文化観光課長","answer":"荏原地区での新規のイベントについてのお尋ねです。時期ですけれども、こちらは今のところ、今年の秋口ぐらいで、先ほど委員から、武蔵小山の各施設、事業概要のところで説明しているところのお話もございました。","voiceIndex":314,"id":"exchange-137"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。荏原地区でも、私の旗の台のほうでも、区境、大田区との境、目黒区との境もあります。そういうこともちょっと踏まえて、旗の台地区に限定しませんけれど、少し距離があるようなところも、これから周知をきちんとやっていただければと思っているのですけれども、そこをちょっと詳しく教えていただければと思います。","respondent":"篠田文化観光課長","answer":"確かに武蔵小山のほうを見ますと、旗の台から少し遠いところではあるのですけれども、荏原文化センターなども含めて開催してまいりたいと考えています。ですので、幅広い荏原地区全体に情報が行き渡るように、私どもも対応してまいりたいと考えているところです。","voiceIndex":316,"id":"exchange-138"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。今、課長から、幅広くということをご答弁いただきました。これは、旗の台、中延地区ですと、今年やるかどうか、まだ分かりませんけれども、毎年、秋の祭礼があります。例えばポスターとか、あと区政協力委員の方々にも協力をお願いするとか、お願いしたいと思うのですけれども、改めてもう一回、ご答弁をよろしくお願いします。","respondent":"篠田文化観光課長","answer":"その中には当然、地域の皆様方や商店街関係の皆様方を含めてお入りいただきながら、それぞれご意見も伺いながら進めていきたいと思っていますので、そういった場も活用しながら周知にも努めてまいりたいと考えているところです。","voiceIndex":318,"id":"exchange-139"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１８９ページの歩行喫煙防止推進経費、それから次に、１９３ページの区民作品展、それから１８５ページ、町会・自治会ＩＣＴ活用促進補助についてお伺いしたいと思います。このことについて、まずお知らせください。","respondent":"森田生活安全担当課長","answer":"路上喫煙禁止・地域美化推進地区につきましては、おおむね、マナーアップ啓発も実施、また生活安全パトロールも実施しています。それ以外につきましても、ポイ捨てや歩きたばこにつきましては指導しています。","voiceIndex":322,"id":"exchange-140"},{"speaker":"塚本委員","kind":"質問・要望","question":"それで、やはりコロナということもあるのかもしれませんけれども、いろいろなところでたばこが吸われていると。そうなると、公園課が禁止している公園においての喫煙等も、関係機関としての例えば警察などが、取り締まると言うと、ちょっと言葉がきついですけれども、注意とか指導とか、こういうこともやっていただきたいという思いがあるのですけれども、現状いかがな認識でおられるのか、お伺いします。","respondent":"森田生活安全担当課長","answer":"警察につきましては、警察に１１０番等があれば、これは独自に警察で対応しているということで認識はしておりますが、私どもから警察に一緒に行ってもらうとか、そういった事案というものは今のところございません。","voiceIndex":324,"id":"exchange-141"},{"speaker":"塚本委員","kind":"質問","question":"こういう実態等が、１１０番された方からの情報として得られれば、あえてそこを狙い撃ちではないですけれど、この時間帯にちょっと行ってみて、現場を押さえてと。あらかじめ、前もってそこを予定して行って、現場を押さえられれば注意しようといったこともやっていただければいいのではないかと思いますが、この辺についてはいかがでしょうか。","respondent":"森田生活安全担当課長","answer":"警察については警察のほうで、独自にいろいろな１１０番が入っておりますし、相談事も入っておりますので、対応はしていると聞いております。","voiceIndex":326,"id":"exchange-142"},{"speaker":"塚本委員","kind":"質問・要望","question":"新しい観覧、もっと多くの方に見てもらおうというような意味も含めて、いわゆるバーチャル空間を活用した展示というのですか、こういったことを少し考えてみたらいかがかと思います。最近、メタバースということで、仮想空間がすごく話題になりましたけれども、いわゆる現実にある渋谷のまちみたいなものを仮想空間に再現するというのですか。","respondent":"篠田文化観光課長","answer":"ただ、委員からお話があったとおり、例えば今般のコロナ禍のような状況ということを踏まえれば、将来的にそういった可能性も、当然考えていく必要があるだろうとは思っていますので、今後の研究課題と捉えていきたいとは思っているところです。","voiceIndex":328,"id":"exchange-143"},{"speaker":"塚本委員","kind":"質問・要望","question":"今現在は、やはりいろいろ課題がありますよね。見る側もヘッドセットみたいなものをつけないといけないので、あれは結構、そんなに単価は安くないでしょう。こういったデジタル系の芸術というのも作品としてどんどん出てきているので、こういったものの作品展というか、区としての後押しも、今後、視野に入れていただきたいと思いますけれども、いかがでしょうか。","respondent":"篠田文化観光課長","answer":"今般、こういった世の中ですので、デジタルでも、新たな、そういった芸術作品等、様々出てきているという中で、現状ではなかなかそこまで手が伸ばせていないところではあるのですけれども、そういった発表の場の提供というのも。","voiceIndex":330,"id":"exchange-144"},{"speaker":"塚本委員","kind":"質問","question":"よろしくお願いしたいと思います。ホストをやってくれるとか、いろいろミーティングをスケジュールして、招待ＵＲＬを対象者に配信するとか、そういったいろいろな運営面をサポートしてくれる人に対する経費というのも、この補助の対象として考え得るのかどうかというのを教えてください。","respondent":"川島地域活動課長","answer":"今のご質問のところですが、ＳＮＳ講習会の講師等の方の経費も、補助対象にしようと考えていますし、今言ったように、Ｚｏｏｍ会議の運営の支援をしていただいたり教えていただく、例えば地域活動団体でも、そういったことを今、得意にしているところがありますので。","voiceIndex":332,"id":"exchange-145"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、２０１ページ、旧東品川清掃作業所暫定活用、１８５ページ、八潮地区まちづくり事業、１７９ページ、職員研修費と、総合実施計画は絡むので一緒に聞きます。４年間ぐらいと考えると、４,０００万円から５,０００万円ぐらいランニングコストがかかるのかというところで、約４億円近くかかっていくのかと考えていますが、どれぐらいの費用がかかるかというところを、まず教えていただきたいです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それで、その翌年度からは、それが通年となりますので、倍弱ぐらいですか、委員がおっしゃるように、五、六千万円ぐらいの運営費になるかと認識しております。","voiceIndex":335,"id":"exchange-146"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、４億円強かかっていくのかと考えていますけれども、皆さんのほうがよく理解されていると思いますが、天王洲は、この地域の皆様の大変なご努力があって、にぎわいになる。特に暫定だし、そういうことをやっていくことが、将来に向かっての有効活用にもなっていくのだろうと私は思っているので、こういう活用の仕方をしていただきたいと思うのだけれども、その辺の考え方を教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"パラスポーツやアーティストの活動の場所としては、無料でお貸出しするつもりですけれども、委員ご指摘のように、イベント等に関して、どのように行政財産として料金を取れるのかなど、その辺りはこれからの検討課題ではありますが、そこがまた区の観光の拠点となって。","voiceIndex":337,"id":"exchange-147"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それで、八潮のまちづくりについて伺います。この辺も、地域の方々に伺うと、なかなかあまり交流がなくて、何か触れられない施設になっているようなところもあって、ぜひこういうところも、今後、八潮の中で全体計画を見ていくときには、その辺のところもぜひ入れ込んでいただいて、よりよい八潮のまちづくりを進めていっていただきたいと考えていますが、その辺の考え方を教えていただきたい。","respondent":"川島地域活動課長","answer":"冒頭お話しいただきましたような過去の経緯なども大事にしながら、計画を進めていきたいと考えています。","voiceIndex":339,"id":"exchange-148"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"過去の経緯もぜひ大切にしていただきたいし、それがどういう形を取るかということであります。それから、政策立案能力が重要だと私は思っておりますが、その辺の部分もどう考えていくのか。こういうものも、どうやって評価していこうと今は考えていらっしゃるのか、どういうふうに取り組もうと考えていらっしゃるのか、教えていただきたいと思います。","respondent":"崎村人材育成担当課長","answer":"来年度については、課長級のマネジメント研修として、そういった能力開発の支援、また次代の課長級管理職を目指す職員をどう育てていくかという部分の重要性を認識させるための研修というのも実施していきまして、区全体として、人材育成。","voiceIndex":341,"id":"exchange-149"},{"speaker":"石田（秀）委員","kind":"意見","question":"最後にお願いだけしておきます。短期で管理職試験を受けているような人、こういう人はもちろん、行政間の交流もあるけれども、民間、外部に、１年ぐらい行ってもらう。こういうのはもう、民間では当たり前に海外に行ったり何なりしています。こういう方々にそういう体験をしてもらうことも必要だと思いますので、ぜひそれはお願いだけしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":343,"id":"exchange-150"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1148#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":117126,"voices":344}},{"id":"r04-20220307-10","meetingId":"r04-cm03","date":"2022年3月7日","dateIso":"2022-03-07","committee":"議会運営委員会","time":"午前 ９時００分～午前 ９時０５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5452#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":2023,"voices":13}},{"id":"r04-20220308-3","meetingId":"r04-c-budget","date":"2022年3月8日","dateIso":"2022-03-08","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を160件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"提案","question":"おはようあります。先日のお話ですと、品川区でも、まずは調査して、研修・研究を行っていく、そういったお話でしたが、１点だけ、またちょっとしつこいようですけれど、その動画の取組というのをご提案させていただきたいと考えています。これから３年間の予算というものがありますけども、こういった予算がなくても、品川区が本気になるべきと私は考えていますので、ご見解をお聞かせください。","respondent":"山下子ども家庭支援センター長","answer":"子どもたちへの周知というところで、アニメーションでしたり、いわゆる動画というものの活用というのは、一定やはり有効性があろうかと考えておりますので、今後庁内で検討してまいります支援策の検討の中で、動画の活用というところも含めて考えてまいりたいと考えています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"たしか武井壮さんか何かがやられるというお話はお聞きします。次に、認知症ミーティングセンターになります。２０２５年、高齢者の５人に１人が認知症になると言われている中、この度のプレス発表で、本人ミーティングの要は進化版というのですか、ちょっと表現が分からなかったのですけど、これが都内初となります、（仮称）認知症ミーティングセンターの開設とありました。","respondent":"宮尾高齢者福祉課長","answer":"ミーティングセンターは、認知症ご本人とご家族の方、ご本人の方が、例えば医療機関で診断を実際にお受けになられて、認知症というふうに診断をお受けになられた直後のような、タイミングとしてはそういうタイミングで、ご本人、ご家族。","voiceIndex":6,"id":"exchange-002"},{"speaker":"松澤委員","kind":"質問・要望","question":"７月に事業開始とあります。準備も大分進んでいると思っていますが、どのようなイメージでセンターというものを計画しているのか、教えていただきたいです。要は、どこか場所を１か所決めてそこでやっていくのか、それとも地域をいろいろ回りまして、分散していろいろな形で開催するのか、そこら辺を教えてください。","respondent":"宮尾高齢者福祉課長","answer":"ですので、今回の予算としては、３か所分の開設支援経費を計上させていただいておりまして、実際に、日頃から認知症の方のケアに関わっていただいている事業者の方、こういった方にぜひ、こちらのミーティングセンターをやっていただきたいということで考えております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"例えば、カフェがあるとすると、その認知症カフェがあるところにサポーターがいて、そういう方とまた一緒に交流できるような、そういった機会をつくるとか、その後の活かしというのですか、そういうのがとても大切だと私は思っております。関わり合いが長いその先輩たちにとっては、失礼で、分かっているというお話になると思いますけれども、そこら辺の考え方を教えてください。","respondent":"宮尾高齢者福祉課長","answer":"ミーティングセンターの運営に当たっては、実際にそれをやっていただきたい、やってほしいという方がいらして初めて成り立つものです。ですので、そういう方々のご意見等をしっかりとお伺いしながら、丁寧に進めてまいりたいというふうに思っております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"松澤委員","kind":"意見","question":"ぜひ、この取組が区民に周知されまして、また、先ほど言いました、各地域で盛り上がる、要は、品川区以外の区で盛り上がりを見せて、また、各地域、品川区全体で定期的に開催できることを願いまして終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"民生費に関連をして伺ってまいります。２２３ページ、日常生活用具給付事業、自家発電装置について、２２９ページ、障害児支援事業に関連をいたしまして、馬とのふれあいについて伺います。２７３ページ、フードパントリー事業、２６９ページ、オアシスルーム・ポップンルームの運営から、キャッシュレス化のスケジュール等、伺ってまいります。昨年の予算特別委員会でも伺いました。","respondent":"櫻木生活福祉課長","answer":"こちらの事業は、想定としましては、ＮＰＯや事業者が生活困窮者に向けたフードパントリーを実施する際に、区が費用について助成する事業となります。具体的には、事業者が区と連携してフードパントリーを開設した際に、立ち上げ費用や運搬経費を助成するというものです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"新妻委員","kind":"意見","question":"この２０２回の利用者も昨年よりもかなり増えていると認識をいたします。まだまだコロナの影響を大きく受けている、またこれからも受けられる方もいらっしゃると思います。このような事業展開、大変にありがたく思います。それと、この福祉関連の事業者において、利用者の方がどのような仕組みで利用ができるのか、そこら辺のご説明をお願いいたします。","respondent":"櫻木生活福祉課長","answer":"いつからですが、事業者のほうでご検討されている状況ではあるのですが、６月頃を目標としたいというお話を伺っているところです。","voiceIndex":16,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"最初のこのきっかけというのは、暮らし・しごと応援センターになるのでしょうか。区役所に来られる方だけでなく、お困りの方はたくさんいらっしゃると思います。そういう方の目につくところにこの周知がされるということが非常に大事だと思いますので、その周知の仕方についても、もし今検討されているようであればお考えをお知らせください。","respondent":"櫻木生活福祉課長","answer":"周知につきましては、チラシ等を作成して、お困りの方にどのような形で目につくような、届くような形で周知できるかということは、これから考えてまいりたいと考えています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"昨年１０月と今年の２月、八潮地域では大きな停電が２回ほど起こりました。その際に、障害者福祉課長にも、八潮地域で人工呼吸器を使われている方の状況はどうなのかということを確認させていただきましたが、大きな災害が起こらなくても、このような停電が半年も経たないうちに２回も起きているということは、本当に、人工呼吸器等々を使っていらっしゃる方においては大変ご心配だったことと思います。","respondent":"松山障害者福祉課長","answer":"それぞれ、使用者の状況ですけれども、ご自分で準備をされている方もいらっしゃれば、全く準備をされていない方もいらっしゃいますので、今後、周知に努めてまいりたいと考えております。","voiceIndex":20,"id":"exchange-009"},{"speaker":"新妻委員","kind":"意見","question":"それと、まず、今回台数をどれぐらい予定されているのかということと、１７人それぞれ、ご自宅で持っていらっしゃる方もいらっしゃるということなのですが、今後、この給付に当たって、どのような流れでこれが給付をされていくのか、お一人おひとり、こういう事業が始まりますよということは、団体を通じてもぜひ周知もお願いしたいところなのですが、具体的にしっかりと給付。","respondent":"松山障害者福祉課長","answer":"そのため、今現在、保健師や相談員、障害者福祉課の職員がお一人おひとりの個別計画に携わっておりますので、直接ご相談をして作成する形でのご案内ということで、漏れなく周知してまいりたいと考えております。","voiceIndex":22,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"１７名漏れなく全員ということ、もし台数が足りないということであれば融通を利かせていただいて、全ての方がご自宅に設置されるよう、取組を要望します。続きまして、障害児支援事業から関連をいたしまして、馬とのふれあい事業についてお伺いをいたします。今後、教育部門でも確認をさせていただこうと考えていますが、福祉部門におけるこの馬との触れ合い事業についての見解をお伺いいたします。","respondent":"松山障害者福祉課長","answer":"障害のある方と馬とのふれあい事業についての見解です。同イベントについては、私どもも承知しておりまして、以前より、馬とのふれあい事業については、知的障害者のみならず重症心身障害児もかなり触れ合いがあり、コロナ禍の中で効果的なものだと認識をしております。","voiceIndex":24,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"新年度も計画がされているとも聞いておりますけれども、それは今、団体として、団体と東京都競馬株式会社が直でやっていることでありますが、今後ゆくゆくは品川区もしっかりと応援をしていただける、そういう事業展開を要望させていただきたいと思いますので、また引き続きつる委員とともに、取り上げてまいりたいと思います。最後に、オアシスルームについてお伺いをいたします。","respondent":"初貝保育教育運営担当課長","answer":"今後の予定ですけれども、次年度というところで、今現状やっているところに加えて、ほか８か所を追加して行う予定でございまして、計９か所を実施する予定です。","voiceIndex":26,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"計９か所となるということです。オアシスルームはたしか１２か所でしたでしょうか、全部が展開できないというのは何か課題があるのでしょうか、お伺いします。","respondent":"初貝保育教育運営担当課長","answer":"来年度は９か所で実施を予定するというようなところですけれども、その利用状況等々、実績を踏まえた上で、順次キャッシュレス化の施設を拡大する予定ということで、まずは来年追加でというようなところで考えております。","voiceIndex":28,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問","question":"早急に全てのところでキャッシュレス化ができますよう、よろしくお願いいたします。最後に、これも何回も取り上げておりますが、全区展開ということで、八潮、勝島地域におけるこのオアシスルームの設置について、状況をお伺いいたします。","respondent":"初貝保育教育運営担当課長","answer":"この間、区有の施設を中心に検討を進めているところです。しかし、様々施設の問題であったり調整がなかなか難しかった部分もありますけれども、引き続き適地を検討しまして、実現に向けて検討していきたいと思います。","voiceIndex":30,"id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは２４５ページ、子ども・若者応援事業、児童相談所移管推進事業、２５１ページ、ひとり親家庭支援事業についてお伺いいたします。１点目に、子ども・若者応援事業についてお伺いいたします。日本は親に働きかけるエージェントが少ない。とんでもない親ではない。商業・ものづくり課の部分については産業経済費のところでお伺いいたしますが、若者等社会参加の観点からの考え方を教えてください。","respondent":"廣田子ども育成課長","answer":"今後につきましては、起業と就業の支援の部門についても連携していくように検討していこうと思います。","voiceIndex":33,"id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に、児童相談所移管推進事業についてお伺いいたします。区におきましても、今後、国や民間企業などのＥＢＰＭ推進の動きを注視しながら政策立案に取り入れていただきたいのですが、区のお考えをお聞かせください。同じく、社会的養護施設退所者等への支援につきましても、今後区でも開設に当たりまして準備を進めていただきたいと考えていますが、区のお考えをお聞かせください。","respondent":"佐藤企画調整課長、加島児童相談所移管担当課長","answer":"２点目、区の政策に取り入れてはどうかですが、ＥＢＰＭ実施のポイントといたしまして、アウトカムと呼ばれる定量的な指標を目標となる数値として設定するのが通常でございまして、区においても。私どもといたしましては、今後の国の動きですとか東京都の実施状況などを見ながら、区として必要な支援スキームがどのようなものか、調査研究してまいりたいと考えております。","voiceIndex":35,"id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目に、ひとり親家庭支援事業についてお伺いをいたします。そこで、空き家も増え、民間でもユニークで先駆的な取組が始まっていると葛西先生から伺いました。物件の提供のみならず、ソフトの支援を含めて、入居前の相談、入居後のサポートなど、様々なアクターが得意分野を活かして連携体制を整備していただきたいと思いますが、区のお考えをお聞かせください。","respondent":"伊東子育て応援課長","answer":"入居後というお話もありましたけども、母子生活支援施設ということであれば、全般的なフォローはできるのですけれども、それ以外の部分に関しては、それぞれの課と連携して対応していきたいというふうに考えております。","voiceIndex":38,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"２２９ページ、２３１ページの避難行動要支援者個別計画作成について、障害者および高齢者の個別計画を伺いたいと思います。災害時の対応について、本人も家族もとても不安を感じております。進捗状況と対象者を伺いたいと思いますが、障害者そして高齢者について、作成された個別計画は何件あるのか、また個別計画の対象者について、障害者そして高齢者はどういう方でそれぞれ何人か、伺いたいと思います。","respondent":"松山障害者福祉課長、宮尾高齢者福祉課長","answer":"障害者の方の対象としては、今年度は通所施設のご利用者の方を対象に実施いたしました。１１月に相談支援向けの防災学校を実施して、約１か月、１２月までの数字ですが、１２人の方に作成したところです。今年度は、同じく原案の段階で５,０００件の作成を予定しています。障害者のほうと同様に、高齢者につきましても、ケアマネジャーを対象に、防災に関する研修の実施を今年度はしたところです。","voiceIndex":41,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"障害者のほうを伺いたいと思いますけれども、通所施設の方を対象に進めて今、１２件というご説明でした。視覚、聴覚、知的、精神、身体、内部障害も含めて、全ての障害を持っている方に個別計画を対象にしていただきたい、進めていただきたいと思うのですけれども、現段階はそういうことですが、対象は、全ての障害を対象にすることを目指しているのかどうか、その点を伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"初めて災害について考えたり、備蓄、日頃の備え、地域との関係について話し合いながら、今、作成しているところですが、一番の課題といたしましては、避難誘導支援者につきましては、なかなかそこが記載できない。","voiceIndex":44,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"この障害者の支援について、大地震や風水害の際、在宅避難をされる方、また自宅を失って避難所での生活をされる方、避難生活を続けるに当たってどういった支援が必要なのか、必要となる支援がどのように、障害によって変わってくるのか。支援者を募る意味でも、例えばパンフレットなどを作成して、当事者への説明と併せて、地域住民への理解を広げていく取組が必要だと思いますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"当然ながら、地域住民の方とともに避難したり、避難生活を送るということは想定されますので、必ず私どもで地域の理解というのを促進していく必要があります。日頃からの障害者理解の促進とともに、防災課と連携しながら普及啓発をしてまいります。","voiceIndex":46,"id":"exchange-020"},{"speaker":"中塚委員","kind":"提案","question":"息子に知的障害があるというご両親にお話を伺いました。正直言って学校など集団での避難生活は困難なので自宅しかないと、一定の備蓄はしていても大地震の際に避難生活が長期化したらどうなるのかと。水や食料と併せて、薬の確保ができるのかと、様々不安をおっしゃっておりました。それがいずれ、個別計画の作成を加速させていくと思いますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"その中でやはり、当事者やご家族が改めて災害時の避難について、世帯で考える、家族全体で考えるきっかけとなっております。それが一番の普及啓発だと考えております。","voiceIndex":48,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、この支援者を募るためにも、障害がある方がこういうことが困るのだと、支援を、例えばいわゆる災害ボランティアに参加してくれる方、ぜひ協力してほしいと、そういう取組を強めていただきたいと思います。ぜひ連携して訓練も進めていただきたいと思いますが、連携についていかがでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"ただ一方で、やはり実際に、日頃からの高齢者の方のケアに介護保険上関わっていただいている方のサポートなくしては、福祉避難所の運営は成り立たないものというふうに認識をしておりますので、しっかりと施設側とも連携協力をしながら、訓練の実施も含めて。","voiceIndex":50,"id":"exchange-022"},{"speaker":"くにば委員","kind":"質問・要望","question":"本日は、２３１ページ、熱中症等予防対策、２６９ページ、オアシスルーム、２３５ページ、ＩＣＴ見守りシステム設置から伺ってまいります。私は、昨年１１月の一般質問で、この高齢者の熱中症予防のためのエアコン設置助成を求めました。高齢者の夏の熱中症の約４割は夜間に発生しており、その多くはエアコンをつけていませんでした。そこで改めてお伺いいたします。もう１点お伺いいたします。","respondent":"宮尾高齢者福祉課長","answer":"今年の夏の予想というところありましたけれども、まずは、そのベースでしっかりと周知啓発を図っていくとともに、必要に応じてケアマネジャー等の方に見守りを行っていただく、それから必要に応じて物資をお配りする、あるいは扇風機等をお貸しする。","voiceIndex":53,"id":"exchange-023"},{"speaker":"くにば委員","kind":"意見","question":"要するに３３％の方は設置していないとのデータなのです。例えば本区においては、全国的なデータよりも経済的に余裕がある方が多いので、その設置台数はもっと多いというような認識なのか、それとも、３３％の方はあくまで少数だから、そこは対象にせず、もう６７％が相当数ということだからまあいいでしょうという感じなのか、ちょっとそこの数字に関しての認識についてご答弁ください。","respondent":"宮尾高齢者福祉課長","answer":"どういう事情でつけていらっしゃらないのかというところも含めて、しっかりと、これから夏場を迎えていくに当たって、お一人暮らしのご高齢者の方を訪問する際には、そういった説明も含めて、対処していくという必要があるというふうに認識をしています。","voiceIndex":55,"id":"exchange-024"},{"speaker":"くにば委員","kind":"質問","question":"今のご答弁の中でありました、エアコンを設置してない方が決してその経済的な事情で設置をしていないというわけではないというご答弁でしたけれども、私は一般質問の際も申し上げましたけれども、経済的な事情だけではなく設置していない方もいらっしゃいますけれども、経済的な事情で設置ができない方も相当数いらっしゃいますというふうに申し上げました。","respondent":"宮尾高齢者福祉課長","answer":"そういったことも含めてしっかりとアセスメントをしていく必要があるということは、それはしっかりと認識としては持ち合わせております。","voiceIndex":57,"id":"exchange-025"},{"speaker":"くにば委員","kind":"質問・要望","question":"ちょっとこれに関しましては、次の質問がありますので要望としてお伝えさせていただき、この質問を終わらせていただきたいと思います。先ほど新妻委員のほうから、八潮、勝島地区のオアシスルームについて、設置要望の質疑がありました。それならば、積極的に民間の施設を中心に検討すべきではないかと思います。区有施設以外で、これまでどのような施設を検討していたのか、その２点をお伺いします。","respondent":"若生保育支援課長","answer":"様々検討を進めていく中で、民間の施設等も含めまして広く、今後も検討してまいりたいと考えています。","voiceIndex":59,"id":"exchange-026"},{"speaker":"くにば委員","kind":"質問・要望","question":"今質疑で私が求めたのが、まず、今私が申し上げた２か所等については、今まで検討の俎上に上がっていたかどうかという１点と、区有施設以外で、今、民間の施設を活用という形でおっしゃいましたけれども、区有施設以外でどのような施設を具体的に検討してきた経緯があるのかお伺いします。もう１点、基本的にオアシスルームは今、区内では、区立の保育園を中心に併設されているところが大半だと思います。","respondent":"若生保育支援課長","answer":"そういったところについては、民間のオーナー等々の関係もありますので、区としても可能な限り検討を進めていきたいと考えています。","voiceIndex":61,"id":"exchange-027"},{"speaker":"くにば委員","kind":"質問・要望","question":"すみません、民間の施設が含まれていることは、私ちょっと誤認識しておりました。失礼いたしました。ですので、やはりその近くの地域にオアシスルームがあるということは非常に重要だと思いますので、そこに関して重ね重ね、ぜひご検討のほうお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"私からは、２２３ページ、障害者グループホーム運営費助成、それから２２１ページの手話理解促進でいいかなと思うのですけど手話通訳者への支援、それから２２３ページ、医療的ケア児地域生活支援促進事業、それから２２９ページ、重症心身障害者通所施設運営費、それから２４０ページの児童福祉費で、ちょっとどこの項目かは不明なのですけれど、子どもの意見表明・権利擁護について。","respondent":"松山障害者福祉課長","answer":"私から、障害者グループホーム運営費助成の詳細についてお答えいたします。有資格者についてですが、１つのグループホームにつきまして、有資格者は２名を上限としております。","voiceIndex":65,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。手話言語条例が制定されて手話通訳者の方の出番も増えて、求めてきたことなのですけど大変だなと思っています。区登録手話通訳者の方からもご意見いただいていますし、区へもご要望があって実現したということだと思います。歓迎します。これが十分なのかちょっと判断がつきませんので、その辺について見解を伺います。併せてぜひ治療費補助も検討してほしいのですが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"区としましては、手話通訳者の頸肩腕等のご健康についても、今後も配慮してまいります。","voiceIndex":67,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、歓迎する一方で、忙しくなってしまうなということでちょっとどきどきしておりまして、通訳者の方たちの報酬は十分とは言い難く、家計を支えるための仕事としては難しいというふうに伺ったことがあります。これは要望とします。こういう場合、区として全額ではないまでも、障害者差別解消という視点から、手話通訳者配置のための補助制度を検討していただきたいと思うのですが、いかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"こちらなのですけれども、法律で、合理的配慮の提供が義務化されているものですので、サービスの提供の実施者側で提供するということが基本になってくるものと考えております。","voiceIndex":69,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぐるっぽにも、障害児者総合支援施設担当として１人配置していますが、こちらは現指定管理事業者が建物の管理ができない部分の施設管理を担っているということで、秋に、指定管理事業者が交代になった段階で、全館を指定管理事業者が管理するということで、こちらの方は区のほうに戻ると理解しているのですけれど、それでピッコロのほうに配置されている職員の方の位置づけについて伺いたいと思います。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"こちらのピッコロは区の直営の事業です。施設ではないため、指定管理者ではなく、区の組織にその職員も、重症心身障害者通所事業担当として、組織の中に位置づけているというものです。ぐるっぽにおける区の職員の配置についてですけれども、現在は建物管理ということで役割を担っているのですけれども、それと同時に地域拠点施設といたしまして。","voiceIndex":71,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"ちょっと位置づけはお二人それぞれ違うけれども、それぞれ理由があって配置ということですかね。それで、利用者の方も、その運営事業者が十分そこの事業をされているということで、例えばそこに区の職員がいるということで、ちょっと私もこの辺の解釈は全然詳しくないのですけれど、一般的に偽装委託とか偽装請負とか、そういう解釈がされる危険性はないのでしょうかということが１点。","respondent":"松山障害者福祉課長","answer":"ピッコロに関しての委託については、こちらのほうも東京都の指定をきちんと受けておりますので、何か請負とかそういったことでは一切ございません。それから、職員の異動の案件につきましては、人事案件ですので個別案件につきましてはちょっとお答えは控えします。","voiceIndex":74,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。そうですよね、人事の関係ということですよね。そうすると、これ、人事課のほうに聞かなければいけないのかなと思うのですけども、やはりこの方の役割というのが、施設を利用されている方たちにとっても、ちょっと戸惑いの元というか、そういうようなことを伺っております。ぜひ活用を進めていただきたいという視点から、区がその活用状況をどのように考えているのか伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"ただ一方で、やはり委員ご指摘の、送迎を含めた預かりの通所サービスを実施してほしいというようなお声もありまして、現在ベルの方向性についても事業者と協議しています。","voiceIndex":76,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"送迎検討ということなのですけど、叶うことなら、それで利用が進むということであれば、ぜひ検討していただきたいと思います。こども基本条例の効果ということだと思います。私、第２回定例会の一般質問で、東京都のこども基本条例を根拠に、子どもの意見表明とそれに関連してアドボケイトの仕組みを求めたところ、確か、国の動向を注視して検討するという趣旨のご答弁だったというふうに理解しています。","respondent":"加島児童相談所移管担当課長","answer":"今ご質問の点につきましては……。","voiceIndex":78,"id":"exchange-035"},{"speaker":"木村委員","kind":"確認","question":"私からは、２１５ページの上から４行目、高齢者安否確認事業の中の、その３行下にあります、長寿お祝い事業からの質問をいたします。健康寿命も毎年伸びている昨今ですけれども、区内在住の高齢者の皆様をご覧になり、昔と今の高齢者とでは変化を感じること、違いを感じることというものは何かあるでしょうか。","respondent":"寺嶋福祉計画課長、菅野高齢者地域支援課長","answer":"ただいま、委員からご指摘いただきました事業につきまして、長寿お祝い事業は、米寿、卒寿、白寿等のいわゆる切りのいい年齢のところでお祝い品を贈呈するという、安否確認も兼ねてお祝い品を贈呈する。令和３年につきましては、９月に実施予定だったのですが、残念ながらコロナによる緊急事態宣言がありましたので、オンラインによる記念式典と記念講演のみを実施させていただきました。","voiceIndex":81,"id":"exchange-036"},{"speaker":"木村委員","kind":"意見","question":"元気な品川に元気な高齢者あり。この事業を実行すれば、元気な人生を送ることができるだろうなど、お考えになったことはありますか。そして、元気な毎日を過ごすためには、腹を抱えて笑える、楽しく、気持ちよく汗をかくことは当たり前のように言われていますけども、ほかに何か、高齢で元気に過ごすための極意というもの、何かそういうお考えがあればお聞かせください。","respondent":"菅野高齢者地域支援課長","answer":"高齢者の地域の社会的な活動への参加は、活動を行う高齢者自身の生きがいにつながり、また介護予防や閉じ籠もり防止にもなることから、区において、こうした活動を積極的に支援していきたいと考えているところです。","voiceIndex":84,"id":"exchange-037"},{"speaker":"木村委員","kind":"質問","question":"ずばり、行政としてのサポートはどのようなことができるとお考えでしょうか。そして、これからのこの計画の中で、これは実行に移したいということはあるのでしょうか。許せる範囲で結構ですが、区独自のアイデア等があれば、それもお聞かせください。","respondent":"菅野高齢者地域支援課長","answer":"区としてのサポートというところなのですけれども、高齢者が社会参加することは、社会的役割を持つことは、高齢者の生きがいや介護予防の効果が期待できるということは先ほど申し上げましたが、元気な高齢者をはじめとした。","voiceIndex":86,"id":"exchange-038"},{"speaker":"木村委員","kind":"質問","question":"ぜひともすばらしいサポートをお願いいたします。次に、２３１ページの中ほどの下にありますけれども、高齢者災害対策支援事業費、５,９１９万円余からの質問であります。そして地震だけではなく風水害も同じですが、災害に対し、本区も同じようなお考えでしょうけれども、品川区がほかの自治体と違った独自の対策等をお考えになっていることがあれば、許せる範囲でお聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"こういう方に対して、きめ細かくどうやって支援をお届けするか、こういう視点を持ってこれからも進めてまいりたいと考えています。災害の避難についても同様の考え方で進めさせていただいているところです。","voiceIndex":88,"id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"私からは２４９ページ、子どもすこやか医療費助成事業および２５３ページ、ひとり親家庭医療費助成事務についてと、２６１ページの保育所等の巡回支援事業について伺います。子どもすこやか医療費助成事業のうち、高校生等入院医療費助成について伺います。手続について伺います。","respondent":"伊東子育て応援課長","answer":"高校生の医療費助成ということで、入院費に限定したところですけども、区は他区に先駆けて実施しています。","voiceIndex":92,"id":"exchange-040"},{"speaker":"松本委員","kind":"質問・要望","question":"平日の１７時までということなので、これは実際に、働かれている保護者の方たちからすると、相当負担だと伺っています。コロナ禍で、できるだけ来庁しないようにというふうに言っているところもありますので、この高校生等入院医療費助成、そして中学生までの医療証を使っていない場合の東京都外で受けた場合の支給申請について、郵送申請や電子申請を導入すべきと考えますが、区の見解を伺います。","respondent":"伊東子育て応援課長","answer":"その原本をもらうということでの担保が何かしら考えられればその可能性もあるのかなというところで、もう少し検討させていただければと考えています。","voiceIndex":94,"id":"exchange-041"},{"speaker":"松本委員","kind":"質問・要望","question":"今の支給とか助成の申請なのですけれども、この医療証について、中学３年生までの医療証についても、逆にこちらは郵送申請可能なのですね。郵送申請可能で、電子申請はできないと。こちらも電子申請、検討していただきたいと思いますがいかがでしょうか。こちらも、電子申請が難しくてもせめて郵送申請を検討していただきたいと思いますがいかがでしょうか。","respondent":"伊東子育て応援課長","answer":"必要な書類というところで、領収書もそうですけども、その他保険証ですとか様々あるという部分で、こういう形で対応を取らせていただいているところです。郵送に関しては事故があったりということも勘案してということで、来庁ということでしているところです。","voiceIndex":96,"id":"exchange-042"},{"speaker":"松本委員","kind":"質問・要望","question":"ぜひこちらも、具体的に区民の方からのご要望があったところなので、ご検討いただければと思います。次に、保育所等の巡回支援事業について伺います。これプレスリリースで拝見すると、新規で予算計上されているというところですが、あまり時間もないですから一応確認で、法律上の指導検査とこの巡回支援の違いについてお伺いできればと思います。","respondent":"立木保育課長","answer":"巡回支援事業ですけれども、国の要綱に基づき、受託事業者等の支援員が行うものでありまして、区が実施します指導検査のような子ども・子育て支援法や児童福祉法に規定された権限に基づいて行うものではございません。主に助言等を行うことを想定しております。","voiceIndex":98,"id":"exchange-043"},{"speaker":"松本委員","kind":"確認","question":"平成２４年の辺りから、認可については区のほうでというふうになったと思うのですけれども、さらに、ここも確認なのですが、幼児教育・保育の無償化で、指導検査の体制がまた少し変わっていると思うので、そこのところの部分を解説していただけますでしょうか。","respondent":"立木保育課長","answer":"子ども・子育て支援法が施行になりまして、児童福祉法と子ども・子育て支援法と二本立ての形になっております。まだ、児童相談所が移管前ですので、そこの部分はちょっと違いあるのですが、基本的には区のほうにも指導検査権限のほうが下りてくるという形になってあります。","voiceIndex":100,"id":"exchange-044"},{"speaker":"松本委員","kind":"質問・要望","question":"そうすると、これまで以上に体制の整備というのが必要となってくると思うのですが、これは準備というのは、まだまだちょっと先ではあるのですけれども、早めに準備が必要かと思いますが、今、人員体制等の準備状況をお伺いできればと思います。","respondent":"立木保育課長","answer":"令和６年度の児童相談所開設に向けまして、指導検査の体制のほうも、順次整えている段階でございまして、体制の強化等も年ごとに増やしていく形で、計画をしています。","voiceIndex":102,"id":"exchange-045"},{"speaker":"松本委員","kind":"質問・要望","question":"これは初日か２日目でも扱いましたけれども、都と区の権限と予算の関係というのはかなりバランスが悪いようにも思っておりまして、準備は大変だと思うのですけれども、やはり保育事故とかというのが都内でも起こっているところなので、できるだけ区が積極的にしっかりと、事故を防げるように、体制整備をお願いできればと思います。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-046"},{"speaker":"小芝委員","kind":"質問","question":"よろしくお願いします。私からは２６３ページ、特別支援巡回相談、児童の安全対策強化事業助成について、また２６１ページ、保育所等の巡回支援事業についてお伺いをいたします。保育所等の特別支援巡回相談についてです。懸念していますことは、保育士の質です。当時の相談に関連をいたしまして、特別支援保育巡回相談事業について質問いたします。この事業が新たに拡充をされました経緯を教えてください。","respondent":"若生保育支援課長","answer":"特別支援保育巡回相談事業についてのお尋ねです。私立保育園での保育園に対する巡回支援というところで、令和４年度予算のほうで提案させていただいた巡回相談の拡充の内容ですが、これまで、臨床心理士の巡回相談事業で、認可保育所のみを対象として実施していたところです。","voiceIndex":107,"id":"exchange-047"},{"speaker":"小芝委員","kind":"質問","question":"保育所に通う幼児は、母親よりもこの保育士のほうが接する時間が長くなることもあります。場合によっては、母親が子どもの特性に気づかないこともあるかもしれません。保育士がその幼児の特性に気づくこともあり得るわけですが、そのような場合に、保育所は、この特別支援保育巡回相談で臨床心理士などとどのように連携を取っていくのか、入り口のところをぜひちょっと教えてもらいたいと思います。","respondent":"若生保育支援課長","answer":"保護者への対応についても、どういう関わり方をしたらいいかも保育士のほうに助言をするというような形で、連携しながら事業を進められているところです。","voiceIndex":109,"id":"exchange-048"},{"speaker":"小芝委員","kind":"質問・要望","question":"このシステムによって、この保育士の仕事の効率化といいますか、そういったことが進んでいることは分かりましたけども、一方で、機械は機械ですので、壊れることも故障することもあるかもしれませんので、こういったことはもちろん防ぐように、日々の点検を怠ることのないよう、強く求めて次に行きたいと思います。先ほど、午前中松本委員からも質問があったと思いますが、巡回支援事業についてお聞きします。","respondent":"立木保育課長","answer":"巡回支援事業ですけれども、法に規定された指導検査とは別に、巡回支援指導をプラスして実施することによりまして、各保育施設における重大事故の防止や、保育の質の確保・向上を図るという、そういったねらいの下に行うものです。","voiceIndex":113,"id":"exchange-049"},{"speaker":"小芝委員","kind":"質問・要望","question":"この巡回支援事業というのは、年１回の検査、指導検査を待たず助言を行うと書かれていますけども、なるべくこういったことも頻度を多くして進めていただきたいと思いますが、その辺りの考えを教えていただければと思います。","respondent":"立木保育課長","answer":"当面、年２回行う予定ですけれども、様子を見ながら拡大の方向も探っていきたいと考えています。","voiceIndex":115,"id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"２４５ページ、すまいるスクール運営費、２４６ページ、子ども家庭支援センター費、２４９ページ、子どもすこやか医療費助成事業、時間があれば、２６５ページ、地域型保育事業費、２６７ページ、ベビーシッター利用支援事業について伺っていきたいと思います。","respondent":"廣田子ども育成課長","answer":"他区の調査については、令和元年度に区として行っているものと、令和３年度に他自治体が行った簡単な調査のものは手元にあるのですけれども、他の自治体で一部導入しているところにつきましては、父母会、ＰＴＡ等の活動としてやっているというところが多くありましたので。","voiceIndex":118,"id":"exchange-051"},{"speaker":"つる委員","kind":"質問・要望","question":"これは今に始まったことではなくて、品川区も７人に１人が子どもの貧困と言われる、そういう状況下にある、そういう課題が示されている中で、給食が１日の唯一の食事であるというような課題は、これ、全国的なこともあって、先日の質疑で、給食費の１食当たりのものですとか、また栄養価等についてもいろいろと確認はさせていただいて、要は子どもたちのそういう長期の休業のときの食の確保。","respondent":"山下子ども家庭支援センター長","answer":"区といたしましては、これまで子ども未来部という形で、虐待また今後進めていくヤングケアラー支援も含めまして、庁内での体制というところ、また庁内以外に関係機関との連携というところを強めてまいりたいと考えています。","voiceIndex":120,"id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"次の、子どもすこやか医療費助成事業なのですが、過日の代表質問で、公明党からその確認をさせていただいて、これまで品川区がやっている中では所得制限を設けずに、そういったことも含めて、区の見解を求めたところでは、昨今の状況を注視して積極的に検討していくというご答弁をいただいたところでありますが、東京都のほうでこれは、当初予算で今まさに都議会でも審議されているところで。","respondent":"伊東子育て応援課長","answer":"高校生の医療費無償化ということで、都のほうでは令和４年度、７億円ということで準備経費として計上しています。スケジュール感ですけれども、実はまだ正式なといいますか、都からの内容につきまして、スキームに関して来ていないところです。","voiceIndex":122,"id":"exchange-053"},{"speaker":"つる委員","kind":"質問・要望","question":"次に地域型保育事業費についてですが、これは昨年の一般質問ですとか決算特別委員会の段階で求めさせていただいて、一定の所管としての答弁いただいていることとして、地域型保育事業所が定員割れをしてしまった際の補助金ということで、これは他の自治体の事例も含めて確認をさせていただいて、決算特別委員会のご答弁の中では。","respondent":"若生保育支援課長","answer":"今後、品川区の保育全体の在り方、こういったことも含めて、きちんと検討した上で、また再度検討を進めていきたいと考えています。","voiceIndex":124,"id":"exchange-054"},{"speaker":"つる委員","kind":"質問・要望","question":"今、ご答弁いただきました再度検討していきたい、そこに期待をしたいと思います。安心の子育てのためには、その両輪をしっかりと整えるという意味では、そこの辺りも再度検討いただきたい。最後は、広報しながわの子育て支援特集号なのですが、これ、２０２１年度はコロナの関係で発行されていないというふうに認識をしていて、今庁舎の中のラックにあったのは２０２０年度のものなのです。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-055"},{"speaker":"渡部委員","kind":"質問・要望","question":"２次選考の状況は、どうだったのかとか、あと実は今回、０歳児にしても途中から、１歳、２歳にしても、満点ではなくて３０点代半ばぐらいで入られている方もいるわけでして、ですから、状況が今までと相当違うのかなというような認識を持っておりますので、ちょっとご解説といいましょうか、概略を教えていただければと思います。","respondent":"立木保育課長","answer":"本日、保育園の２次選考の発表日です。１次選考の申込者数が３,１０４名で、内定が２,１９１名、不承諾が９１３名ということでしたが、２次選考では、内定者がさらに追加で２７６名で、トータルで不承諾が９７１名ということになりました。","voiceIndex":130,"id":"exchange-056"},{"speaker":"渡部委員","kind":"質問・要望","question":"この間、西村委員の質問だったか、そのオアシスルームのという。例えば保育園の中でそういうことができるのであれば、区民の方の需要とかも見てなのですけど、サービス業の方は土日働いて平日休んでいる人も当然フルタイムでいるわけで、そういったときに、例えばそういう需要がどれぐらいあるのか、研究からでもスタートしていただきたいなとちょっと思っているのですけれど、どうでしょうか。","respondent":"立木保育課長","answer":"今のお話ですと、例えば保育のシェアリングみたいな形になるのかなと思うのですけれども、ニーズがいろいろ変化している中で、保育の預かり方という部分に関しましては様々な事例を研究させていただきまして。","voiceIndex":132,"id":"exchange-057"},{"speaker":"渡部委員","kind":"質問・要望","question":"よろしくお願いします。それでいて、本当に保育需要に応えるために品川区が様々な施策を打っていった中で、当然民間の協力をいただいたわけです。ですから、そういうところまで見据えて、どういうことで活かせるかどうか、考えていっていただきたいなと思います。次の質問に移ります。もう毎回やらせていただいていますが、プレイパークですとか児童センターですとか、２４３ページ。","respondent":"廣田子ども育成課長","answer":"他の自治体の状況をいろいろ確認して、学校内であって、子どもたちの受入れを断らないのがすまいるスクールというところなので、大人数の子どもを一堂に集めますので、どうしたら実現するかというところもかなりのハードルであると思うのですけれども。","voiceIndex":134,"id":"exchange-058"},{"speaker":"渡部委員","kind":"質問・要望","question":"だからその辺はやはり進めていただきたい。それで、前回の一般質問でもお伺いしましたプレイパークであるとか、いよいよ児童センターを検討していくという中なのだけれど、去年の第４回定例会の一般質問でしたか、まだそんなに時間が経っていないのですけれど、進捗状況をお伺いしたいなと思うのと、今回、会派の広報紙、政調会長が頑張ってくれてそのプレイパークのことを載せたら、結構反響があったのです。","respondent":"廣田子ども育成課長","answer":"児童センターの在り方というか、今後の老朽化もありますし、在り方をこの機会にということで、今、令和３年度１月から乳幼児親子や小中高生を対象に、ニーズ、どんなところが欲しいかというところなどをアンケート調査をして今、集計中でございまして。","voiceIndex":136,"id":"exchange-059"},{"speaker":"渡部委員","kind":"質問・要望","question":"児童センターとプレイパークと一緒にいろいろ考えてやっていただけるというのはいいですよね。子どもというのはいろいろな人がいる。それでもって保護者だって、幼児のこういう相談だったらここに行けば面白い話がある、ここに行けばどういう講座があると、いろいろな児童センターに行くわけですから、そういうものの強いところをどんとつくってもいいし、いろいろ考えられることってあるのです。","respondent":"廣田子ども育成課長","answer":"児童センターをただ建て替えるわけではなくてというところで、どういう特色をつけていったらいいのかというところを、アンケートではかなり記述もいただいているので、それを参考に、実際使おうとしている子どもたちの意見を参考にしながら。","voiceIndex":138,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"２５２ページ、児童保育費、待機児解消、２３９ページ、高齢者住宅について伺います。高齢者住宅です。今年度の高齢者住宅募集の応募人数は何人でしょうか。昨年、一昨年の応募人数と入居できた人数についても伺います。","respondent":"菅野高齢者地域支援課長","answer":"ちなみに、令和３年度の申込みは５８名、令和２年度は５５名でした。令和３年度の入居状況ですが、現在、まだ進行形で入居案内の方もいらっしゃるのですけれども、１７名の方にご案内をしています。令和２年度につきましては、１９名の方が入居されております。","voiceIndex":141,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"私の実感から、７０名という申請者数ということですが、実際に入居できる例年の数などを見ても、ちょっと少ないと思うのです。品川区は、高齢者住宅の潜在ニーズを考えますと、申請者数が少ないとは思いませんでしょうか。入居者数は十分だと思っているのか、それぞれ伺いたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"例えば、賃貸住宅への住み替えを支援するものとして、住まいの確保と見守りと生活支援を一体的に提供する、あんしん居住サポートを実施してきました。区の居住支援協議会において、不動産関係団体等と連携し、住宅情報の提供等の支援を実施しております。","voiceIndex":143,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"様々やっていると言いますけれど、私が伺ったのは、やはり高齢者住宅を望む人はたくさんいると思うのです。それと、高齢者住宅の対象となる６５歳以上の単身高齢者の方は何人なのか。何人でしょうか。そのうち賃貸住宅に居住している方の割合ですとか、住宅に困窮される方など、居住の実態というのはどれぐらいつかんでいるでしょうか。伺いたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"このときの７５歳以上の人口が３万９,６６７名ですので、約１８％の方が、７５歳以上の一人暮らしの高齢者ということです。それからしばらく７５歳人口が増加しているということもありますので、単純にもう少し伸びているということで推測できます。","voiceIndex":145,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"７５歳以上ということですし、６５歳以上から応募できるわけですから。広報だけでなくて高齢者の目につくところにチラシやポスターで知らせるなど、制度周知の強化と併せて、やはりそのもの、高齢者住宅の増設を求めたいと思いますが、いかがでしょうか。先ほど質疑がありましたけど、本日は２次選考の発表日ということで、当然選考は既に終わっていますので、２次選考の結果を伺います。","respondent":"菅野高齢者地域支援課長、立木保育課長","answer":"高齢者の住宅施策を進めていく中で、ニーズや費用、国や東京都の施策とのバランスも考えていく必要があり、増設については今後も研究していきたいと考えています。これは１次選考からの継続も含みます。０歳児、申請数が２２１名、１歳児４９５名、２歳児２８２名、３歳児１６６名、４歳児５６名、５歳児２７名で、合計で１,２４７名です。","voiceIndex":147,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"２次選考が終わって、これはすごい数字だと思うのです。特に１歳児、２歳児、３歳児は深刻です。しかし、区は去年も不承諾数は同じぐらいいました。９９６人いたのに、いろいろ理由をつけて待機児童から除外して、待機児は５人と、基本的に解消したという認識です。そういう方々がたくさんいるのです。待機児童は基本的に解消という認識は、現実と乖離していると思いませんでしょうか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"ただ、認可保育園だけでそのニーズを全て満たすことはなかなか難しいところですので、総合的な待機児童対策として、認可外保育施設も認証保育所等も含めて対応しています。","voiceIndex":150,"id":"exchange-065"},{"speaker":"湯澤委員","kind":"質問","question":"よろしくお願いします。障害者の短時間雇用への取組についてですけれども、以前一般質問でもお尋ねしましたが、障害者の短時間雇用については、障害者雇用の法定雇用率は週２０時間以上の就労が対象で、２０時間未満を希望する方の活躍の場がないことから、平成２８年、川崎市が自治体として初めて短時間雇用創出プロジェクトの取組を開始して、現在では神戸市や渋谷区など７つの自治体が取り組んでおります。","respondent":"松山障害者福祉課長","answer":"取組、検討状況についてです。２月１８日に、地域自立支援協議会で就労支援部会を行いました。その中で、短時間雇用を提唱している、東京大学先端科学技術研究センターの近藤先生にご講演いただきまして、就労支援事業所と情報共有を図り、今後について検討しています。","voiceIndex":153,"id":"exchange-066"},{"speaker":"湯澤委員","kind":"意見","question":"まだまだ障害者の雇用については、雇用義務や受入れ努力など、障害者雇用の壁が立ちはだかっていると思いますけれども、品川区が早い段階で、あらゆる区民のニーズに応えていくべきかなと考えていますので、ぜひ前向きな検討をお願いしたいと思います。障害者にとって、長時間労働以外にも、採用時の職務定義がないといった日本型の雇用というのが厚い壁になっていると言われております。","respondent":"松山障害者福祉課長","answer":"様々なご提案を踏まえて、今後何ができるのか、あるいはマッチングする事業者もさることながら、一番必要なのは連携だと考えていますので、関係所管と連携しまして、検討を具体的にしていきたいと考えています。","voiceIndex":155,"id":"exchange-067"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ぜひ、専門家の意見や、先行区の動向を注視しながら、品川区でも週に２０時間以内の短期間雇用を求める障害者と、そして事業者とがマッチングできる、品川版の地域システムを構築していただきたいと要望いたします。次に、福祉ショップ運営費に関してです。そこでお尋ねしたいのですけれども、まず、この立正大学との活動に至った経緯はどういったものであったのか。","respondent":"松山障害者福祉課長","answer":"区といたしましては、非常にいい取組ですし、商店街で障害者の方がつくっているものを販売会として売るというような取組で、しかも大学生が関わってということで、授業の一環として単位が取れるという形での、３者ウィン・ウィンの関係のものだと認識しております。","voiceIndex":157,"id":"exchange-068"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ぜひ連携を取っていただきながら、障害者と健常者が触れ合う機会を今後もたくさんつくっていただくよう要望いたしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"２５３ページ、給食関連で、放射性物質検査項目がなくなっております。これは何でしょう。すまいるスクールのお弁当に仕出し弁当をという、あまり歴史的な経過が分かっていないので、本当に歴史的な経過をきちんと調べてほしいなと思っています。親たちは、長期休業のときには、お弁当だけでは足りないし、ということで、おやつが何とかならないか、ということでいろいろと要望がありました。","respondent":"初貝保育教育運営担当課長、築山障害者施策推進担当課長、伊東子育て応援課長","answer":"委員ご指摘のございました、保育園の給食の放射性物質検査に関しましては、こちら、以前から実施をしているところだったのですが。１つ目の施設改修工事費についてですが、こちらは現在２階に設置されております相談支援事業を１階に移しまして。ということで、特例にかかっている方に関しては支給されなかったということで、クレームというお話でしたけども。","voiceIndex":161,"id":"exchange-070"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜかというと、これは風評被害という観点から区がやるべきなのかということの指摘を、私はさせていただいておりました。「年収で計算するとこんな低いのに、何で私たちはもらえないの、おかしいんじゃないか」という、そういう意見をたくさん伺っております。それから、国なのか、その法整備というのを何か意見として言えるようなそういう仕組みになっていないのかどうか、お聞きしたいと思います。","respondent":"築山障害者施策推進担当課長、伊東子育て応援課長","answer":"障害児者総合支援施設は、障害児者の福祉増進のために、地域生活支援拠点として整備した施設ですので、引き続き、区内に住む障害がある方のご意見等をお聞きしながら。今回、児童手当制度に基づいて実施したというところで、そういうことのご意見があったところではありますけども、区としては、国の制度に従っていったです。","voiceIndex":165,"id":"exchange-071"},{"speaker":"西本委員","kind":"質問・要望","question":"それからやはり、子育て、子どものためにと思うときに、どういう観点で、子どものための制度なのかということをよく考えていただきたいと思います。ですので、いろいろな要望があったり、生活環境が変わったりといろいろなものが出てくると思います。でも、忘れてはいけないのは、子どもにとっての利益というものをしっかりと考えていただいて、施策を講じていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-072"},{"speaker":"田中委員","kind":"確認","question":"給食の放射性物質検査についてです。今、ご答弁でこれまで検出されてこなかったので一旦休止ということでした。この食の安全性を確認するためにも、検査方法を改善し検査を再開すべきと考えますが、見解を伺います。どういったときにもう一度再開ができるのかといったところも、併せて伺います。","respondent":"初貝保育教育運営担当課長","answer":"今どういう形というところは、明確には言えないというところではありますけれども、総合的に考えてというところになると思います。","voiceIndex":170,"id":"exchange-073"},{"speaker":"田中委員","kind":"質問","question":"再開などの様々な状況について伺っています。具体的に今、本当に危機的な状況も生まれてしまっています。どういった状況になったら再開するのか、明確にお示しください。","respondent":"初貝保育教育運営担当課長","answer":"それはもう仮の話ということになってまいりますので、やはりいろいろな状況が今後あるかというところで、そういったところの状況に合わせて、区としても、その辺りで再度検討して、必要であればですが、今の時点では一旦。","voiceIndex":172,"id":"exchange-074"},{"speaker":"田中委員","kind":"質問・要望","question":"例えば、来年度、海洋に汚染水を流すといったことも国が示している中で、では国がそれを流した場合には、もう１回検討がされるのか。再開をするための検討がされるのかとか、そういうちょっと具体的にお知らせいただきたいのですけれども、いかがでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"区といたしましては、ちょっと繰り返しの答弁になってしまいますけれども、やはり状況を総合的に勘案しまして、そういった検討をするかどうかも含めて考えていくというような形になるかと思います。","voiceIndex":174,"id":"exchange-075"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもたちの身体への影響というのを第一に考えていただきたくて、それで生活者ネットワークはこれまでずっと求めています。今、残念ながら新たなそういった危険が加わってしまったのです。この状況の中でもまた再開については、その都度その都度と言いますが、だから具体的にどういうときに検査を再開するかをお知らせください。","respondent":"初貝保育教育運営担当課長","answer":"検査の再開については、やはり一つの状況を捉えて再開するかどうかということではなくて、やはり様々な状況を総合的に勘案して検討しなければならないというところなので、それはその時点で、区として総合的に考えるということで、検討しています。","voiceIndex":176,"id":"exchange-076"},{"speaker":"田中委員","kind":"確認","question":"すぐに再開できる体制は常に整っているということで確認できますか。","respondent":"初貝保育教育運営担当課長","answer":"区といたしましては、その状況を鑑みまして、総合的に考えてというようなところで考えておりますので、ちょっと繰り返しの答弁になってしまいますが、そういったところです。","voiceIndex":178,"id":"exchange-077"},{"speaker":"田中委員","kind":"質問・要望","question":"すぐに再開できる体制を整えていってほしいと強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-078"},{"speaker":"こんの委員","kind":"質問","question":"私からは２３５ページ、介護施設高齢者虐待防止基礎プログラム作成等経費、２５１ページ、女性福祉事業、２７３ページ、伴走型居宅生活見守り支援事業の３つを順不同でお聞きしたいと思います。そうしたことで、なぜこれまで作成されてこなかったのか、なぜ今作成なのか、どういう経緯で作成することになったのか、その経緯と、作成に至った背景も併せてお聞きしたいというふうに思います。","respondent":"宮尾高齢者福祉課長","answer":"基本的には各施設において実施をするものなのですけれども、区のほうでも残念ながら虐待の案件がゼロではないというところを重く見させていただいて、区のほうで実際にプログラムをつくって、そして施設のリーダーの方あるいは管理者の方向けに研修をやらせていただいて。","voiceIndex":182,"id":"exchange-079"},{"speaker":"こんの委員","kind":"意見","question":"そうすると、この、国が基準を改正することによって研修をしていく、従事者の方たちへの虐待防止策だというところで、そうすると、区としての、いわゆる、これまでゼロでなかったこの事案を踏まえて、どういう方針でどのようなガイドライン的なものを作成をしていく、そうしたものを作成して各事業所に示していく、そうしたものをつくるというようなところを想像するわけですが、どういったものをつくるのか。","respondent":"宮尾高齢者福祉課長","answer":"そのために、なぜいけないのか、それから、どういうときに起きやすいのか、そして、そうならないために、各施設でどういう対策を講ずるべきなのか、こういったものをプログラム化して、まずは令和４年度については、私どものほうで主催でやらせていただく予定です。","voiceIndex":184,"id":"exchange-080"},{"speaker":"こんの委員","kind":"質問","question":"様々、その従事者に対してのガイドライン的なところを品川区がつくってくださって、そして研修を初年度されていくということが分かりました。私はこのプログラムがそういったものになっていってほしいという期待もあるわけですけれども、そうした区の対応力と、このプログラムの関連性というか、どういう対応力になっていくのか、その辺を教えてください。","respondent":"宮尾高齢者福祉課長","answer":"ですので、もちろん虐待はいけないという趣旨ではあるのですが、それと同時に、施設の職員とご本人あるいはご家族がよりよい関係を築けていけるにはどうしたらよいかというところまでちょっとテーマを広げて。","voiceIndex":186,"id":"exchange-081"},{"speaker":"こんの委員","kind":"質問・要望","question":"次の質問にまいります。伴走型居宅生活見守り支援事業ですけれども、まず、この事業はどのような事業なのか、何を想定された事業となっているのか、その辺を教えていただきたいのと、支援の対象者、どういう方が伴走して、見守って支援をしていくのか、支援体制など事業の概要と、それから事業費として３３０万円が計上されておりますが、その内訳などもお知らせください。","respondent":"櫻木生活福祉課長","answer":"特に年代を限定するものではないのですが、就労増廃止ということになりますので、比較的、３０代から５０代の方が想定になるのかなと考えています。内訳としましては委託費という形になっております。","voiceIndex":188,"id":"exchange-082"},{"speaker":"こんの委員","kind":"質問・要望","question":"廃止後に受給が再開をしてしまったケースは、年間どれぐらい発生しているものなのか、参考までにお聞きしたいと思います。なかなか難しいと思いますが、支援体制も、もう一度お聞きしながら、どういったことで再開しないように抑制ができていくのか、その辺の目標なども教えていただきたいと思います。","respondent":"櫻木生活福祉課長","answer":"目標と言われるとなかなか難しいところではありますが、基本的にはフォローに入った方々については、そのような状況にならないようにということで考えております。","voiceIndex":190,"id":"exchange-083"},{"speaker":"こんの委員","kind":"質問・要望","question":"４０％ぐらいの方が再開をしてしまっている現状を、何とか未然に防いでいこうというこの取組、大事なことでありますので、目標をお聞きしましたが、それはちょっと見通せるようで見通せないのは理解できます。こうした費用について、ひとり親支援の一環としての観点から、費用負担軽減のための支援をと考えるところですけれども、区のご見解をお聞かせください。","respondent":"伊東子育て応援課長","answer":"その一つの手だてとして公正証書の作成ということで、その取決めをすることによって回収するというようなことが可能となります。我々のほうのご相談の中では……。","voiceIndex":192,"id":"exchange-084"},{"speaker":"のだて委員","kind":"質問","question":"私からは、２４５ページの児童相談所、２４７ページの子ども家庭支援センターに関し、子どもの虐待について伺います。品川区は、コロナ前から虐待相談が増加しており、平成２８年度は３７８件ですが、令和２年度は６２８件と１.６倍に増加しています。この子どもの虐待について、援助が必要なケースが区内でどれだけあると見込んでいるのか、伺います。","respondent":"山下子ども家庭支援センター長","answer":"対して支援が必要な児童の数というところで、その数というのを具体的に洗い出しているものではございませんけれども、相談の件数が増えているという中で、いろいろな支援策を講じまして、新年度の予算でも新たな策を講じておりますので。","voiceIndex":195,"id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"なかなか、状況をつかむというのは難しいとは思うのですけれども、やはりそうした家庭、子どもにしっかりと援助が届くような支援体制を取っていただきたいというふうに思います。１つ、例を申し上げますと、シングルマザーで中学生の子どもが２人いる家庭です。やはりこうした、子どもや親に、また保護者に、子どもの権利条約を周知するということが重要ではないかと思いますが、いかがでしょうか。","respondent":"山下子ども家庭支援センター長","answer":"交通事故という不慮の状況でして、もともと養育についても放棄をしているようなことであれば、やはりネグレクトというところが疑われる中で、例えば、ひとり親支援の係のほうからこちらのほうにご連絡いただいて対応するというようなことも考えられますけれども。","voiceIndex":197,"id":"exchange-086"},{"speaker":"のだて委員","kind":"質問・要望","question":"自分の支配が全て行き届くということで、やはり子ども自身も一人の人間ですから思うようにいかない、親にとっても思うようにいかないことも当然あると思います。ほかの児童センターですとか、産前・産後の支援など、教育部門などとも連携をして周知をしていただきたいと思うのですが、いかがでしょうか。","respondent":"山下子ども家庭支援センター長","answer":"実際に、今、支配という言葉がございまして、親御さんがお子さんを管理するというようなことは、やはり子どもの権利という点からちょっと違うのかなというところがありますので、やはり一人の人間として存在していらっしゃるというところは、委員ご指摘の通りの点がありますので。","voiceIndex":199,"id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ子どもの権利条約も含めて、こうしたことの周知をしていっていただきたいというふうに思います。この中で、そういった状況に今、あるということで、区はその状況を認識しているかということも含めて原因をどのように考えているか、伺います。区立の児童相談所設置時には、同じ状況にならないようにしていただきたいと思いますが、いかがでしょうか。","respondent":"山下子ども家庭支援センター長、加島児童相談所移管担当課長","answer":"品川区子ども家庭支援センターとしましては、今現状としましては、東京都品川児童相談所と連携して、要保護児童、要支援児童の対応に当たっておりますので、引き続きそちらに注力してまいりたいと考えています。一つの自治体で行うからこその機能、強みを活かしまして、児童相談所と子ども家庭支援センターの定期的な情報の共有機会など、仕組みを工夫いたしまして、そのような事態といいますか。","voiceIndex":201,"id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそういった形でやっていただきたいというふうに思うのですけれども、やはり子どもなどが相談に行って、子どもを守る、そうした支援、援助がなかなかできていない部分があるのかなというふうに思うのです。今度、区立の児童相談所が設置をされた場合、現在の児童福祉司などの体制は、東京都の設置の状況よりも改善をされるかどうか、伺います。","respondent":"加島児童相談所移管担当課長","answer":"区立児童相談所の児童福祉司等の体制につきましては、法令の基準に基づき確保を図ってまいります。","voiceIndex":204,"id":"exchange-089"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、予算書２５３ページ、新型コロナウイルス感染症対策経費、２５９ページ、各種児童保育委託の中から病児保育、２６７ページ、認可外保育施設等経費から認可外保育施設について、順次お尋ねしてまいりますので、よろしくお願いいたします。保育所における感染症対策についてお伺いいたします。２０２２年１月からの第６波流行における区内保育所の職員、園児の養成者数はいかがだったのでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"ただいまご質問いただきました、区内の保育園における新型コロナウイルスの陽性者数ですが、令和４年１月から３月２日までの数字ですけれども、園児が９１４名、職員が３５７名となっております。","voiceIndex":207,"id":"exchange-090"},{"speaker":"鈴木（博）委員","kind":"質問","question":"既に１,０００名近い園児がコロナ陽性者になっているようです。保育者から保育者、園児から園児への感染も多く報告されています。このような感染様式の変化に応じて、品川区の保育所における新型コロナウイルス感染予防対策は、状況の変化に応じて何か変わった点はあったのでしょうか。それとも同じ基本的感染対策が継続して行われているのでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"保育園での新型コロナウイルスに対する対応に関しましては、オミクロン株流行以前からも基本的な感染症対策の徹底というところでは、根本的な部分では対応は変わっておりません。そのような対策を引き続き、気を緩めることなく、保育園での現場で取り組んでいるところです。","voiceIndex":209,"id":"exchange-091"},{"speaker":"鈴木（博）委員","kind":"質問","question":"昨年の決算特別委員会でもデルタ株流行下での保育所の感染対策をお伺いしました。今のご答弁で、特にオミクロン株流行においても大きな感染対策の変更はないと理解いたしました。患者にお聞きしても、「うちの保育園でも二、三名はいるみたいです」というお答えがほとんどです。現在の保育所の役割と、保育所が直面している問題点などがあれば、併せてご説明をお願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"現在、保育園の業務では、通常の業務に加えて、新型コロナウイルスへの対応という業務が増しているというようなところですので、区といたしましても、今後、保育園の負担がなるべく軽減されるような形で、引き続き保育課や保育支援課。","voiceIndex":211,"id":"exchange-092"},{"speaker":"鈴木（博）委員","kind":"質問","question":"オミクロン株が保育所で流行している最中、保育所では、園児、保護者、職員などに対する感染対策、自宅待機、療養と登園、職員の労務など、濃厚接触者の特定対応以外にも様々なコロナ対策が現在必要になってきていると思います。保育所が様々な課題を抱えたときに、保育課、保育支援課ではどのようなスキームで支援をなさっているのでしょうか、もう一度お尋ねいたします。","respondent":"初貝保育教育運営担当課長","answer":"保育園での対応に関しても、もちろん案件によって相談内容も様々であります。そういったことを基本的には各保育園から内容を聞き取って、個別に保育課や保育支援課が保健所と連携をしながら相談をして、そういった対応を現在行っているというような状況です。","voiceIndex":213,"id":"exchange-093"},{"speaker":"鈴木（博）委員","kind":"質問","question":"現在の保育所における感染対策としては、マスク着用、頻回な手洗い、換気が基本と考えますが、保育現場のための新型コロナウイルス感染症対応ガイドブック第３版によれば、マスクをできない体調不良児の保育・看護にはサージカルマスク、フェイスシールドなどの目の保護具の使用が推奨されております。","respondent":"初貝保育教育運営担当課長","answer":"手洗い消毒や、定期的な換気を行っているところですけれども、それ以外の通常の保育というところでは、今ご指摘のありました、例えばサージカルマスクであったりフェイスシールドというところは、園児にとって触れ合いが大切ということで認識しておりますので。","voiceIndex":215,"id":"exchange-094"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"嘔吐等の処理には、あと手袋も必要だと思います。これに関連して、全国知事会が２歳以上の園児へのマスク着用を国として進めるように求めた提言が問題となりました。年少児へのマスク着用は慎重にあるべきです。日本小児科学会の提言にもあるように、２歳未満児にはマスクは必要ないし、２歳児でもマスクの着用は慎重な対応を求める意見がほとんどです。","respondent":"初貝保育教育運営担当課長","answer":"区といたしましては、今、委員ご指摘のところもありますけれども、そのような国の方針の内容も踏まえて、一定の年齢以上の園児に対して、一律にマスクの義務づけを行うというような対応は行っていないというようなところです。","voiceIndex":217,"id":"exchange-095"},{"speaker":"鈴木（博）委員","kind":"意見","question":"マスクに限らず医学的根拠のない、例えば次亜塩素酸水の空中散布など、様々な、いわゆる感染策に対しても、保育所でも正しい情報提供をお願いしたいと思います。保育所の職員に対するコロナワクチン３回目の接種の進捗状況と、接種の実施に当たり、現在問題になっている点があれば、それも併せてご説明をお願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"そこで区では現在、保健所と連携を取りまして、優先的な接種の体制を整えて取り組んでいるところです。全体の接種率の進捗に関しては把握しておりませんけれども、各自で優先接種枠に申込み、接種を進めているところと考えております。","voiceIndex":219,"id":"exchange-096"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ワクチン接種の効率的で速やかな実施を強くお願いしたいと思います。このようなオミクロン株に抵抗力を持つ、人的な資源を何か有効に活用できる施策などはないものでしょうか。保育現場では、今回のパンデミックで得られた教訓、経験をどのように今後の保育スタイルと保育所における感染予防に活かしていくおつもりか、最後に質問したいと思います。","respondent":"初貝保育教育運営担当課長","answer":"今、委員のご指摘にございました、既にオミクロン株に感染したことがある方への対応です。","voiceIndex":221,"id":"exchange-097"},{"speaker":"鈴木（博）委員","kind":"質問","question":"病児保育について、決算特別委員会に引き続いてお伺いしたいと思います。前回、デルタ株流行時の病児保育の状況をご報告いただきました。今回はオミクロン株流行下での品川区の病児保育の各施設でのお預かり人数の推移、利用率についてご報告をお願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"令和元年の実績には届かないものの、令和２年度と比較しまして大分多い数字になる見込みです。ちなみに、園ごとの実績としましては、チャイルドサンタでは１９５名、約１１％、ひだまりでは６３２名、約３６％、森のおうちでは７３６名、約４８％の利用率となっております。","voiceIndex":223,"id":"exchange-098"},{"speaker":"鈴木（博）委員","kind":"意見","question":"この間の病児保育所における新型コロナウイルス感染症の患者数について、今、ご説明をいただき、ご報告をいただきました。しかし、風邪症状を呈する軽症のオミクロン株の患者が利用してくるリスクは大きいと思われます。このリスクに対して各施設はどのような対策がなされていると、区は把握されているのか、ご説明お願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"病児施設内で新型コロナウイルスというところは、現在確認できていないという状況ですけれども、病児保育施設における新型コロナウイルスの感染症の対策というところでは、受入れの際に、全国病児保育協議会の病児保育施設受け入れ目安なども参考にしながら。","voiceIndex":225,"id":"exchange-099"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今回の新型コロナウイルス感染症流行下において、病児保育は一定の役割を果たしたと、区は総括されているのでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"このたび、このコロナ禍でも一定数の受入れができたというところで、ニーズの確認、役割が再認識できたと確認しております。今後、新たな感染症が発生した際も、また関係機関と連携を取りながら、引き続き対応していきたいと考えております。","voiceIndex":227,"id":"exchange-100"},{"speaker":"鈴木（博）委員","kind":"質問","question":"病児保育は就労支援だけではなくて、子育て支援のための役割も現在期待されております。次に、無認可保育所の現状についてお伺いします。少子高齢化が進み、保育所の預かり人数も減少し、保育所の集約が今後図られていくものと推定されます。その中で無認可保育所は今後どうなっていくと、区のほうは、今、お考えなのでしょうか。その展望についてお伺いします。","respondent":"若生保育支援課長","answer":"認証保育所、認可外施設などの施設についても、今後の状況によっては大きな影響を受けるものと捉えてあります。待機児童対策を取ってきた品川区といたしましては、今後も、区立園の在り方も含めて考えてまいりたいと考えています。","voiceIndex":229,"id":"exchange-101"},{"speaker":"芹澤委員","kind":"質問","question":"私からは２２３ページ、医療的ケア児地域生活支援促進事業と、２３５ページ、認知症高齢者支援事業、時間があれば２５１ページの養育費相談支援事業についてお伺いをいたします。認知症についてお伺いをしたいと思います。その数字の捉え方についても、多分１００％の方は捉えきれないのだろうと思いますが、その課題についてもまずお聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"推計数ですけれども、国が言っている、高齢者の方のおおむね６人に１人というところで、品川区においてもほぼ同様の分布かなというふうに分析をしています。","voiceIndex":232,"id":"exchange-102"},{"speaker":"芹澤委員","kind":"質問・要望","question":"どういったやり方で数字を捉えているのかが分かれば、後で教えてください。この認知症検診、年齢を絞って実施をしていくというふうにも伺っていますが、このやり方を教えていただきたいのです。認知症検診を受ける際に、多分接種券みたいな券が届くのだと思いますが、それを忘れてしまった場合、例えば免許証や保険証だけで受けることができるのかも併せてお聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"その接種券を実際にお忘れで医療機関に行ってしまった場合ということなのですが、基本的に、今時点で考えているのは、区内の、ここでできるという医療機関のほうに予約を事前にしていただく形で考えておりますので。","voiceIndex":234,"id":"exchange-103"},{"speaker":"芹澤委員","kind":"質問・要望","question":"この認知症のイメージをこれからなるべく変えていって、自分が認知症になったというのが、あまり恥ずべきことではないのだと、誰でも認知症になり得るのだよと国のガイドラインか何かにも書いてあったと思いますが、誰でもいずれ認知症になるという、早い遅いがあれども、誰でも認知症になるのだということで、これから国単位で認知症のイメージを変えていかないといけないというふうに伺っていますが。","respondent":"宮尾高齢者福祉課長","answer":"検診率の、受診率の向上というのは、非常に私どもも大切な、大事な課題だと思っておりまして、まずその一つとして、認知症検診という名称、こちらをちょっと親しみやすい名称にさせていただきたいと思っておりまして、少しでも垣根を低くというところで、物忘れ検診ということで。","voiceIndex":236,"id":"exchange-104"},{"speaker":"芹澤委員","kind":"質問","question":"認知症のイメージをぜひ変えていただいてというところで、前向きなお話もいただきました。認知症サポーターについてもお伺いしたいと思います。認知症サポーターをどんどん広げていくという意味で、会社単位で従業員に多く受けてもらっている会社というのもかなりあると思うのです。","respondent":"宮尾高齢者福祉課長","answer":"ただし、一度過去に受けた方に対するアプローチというのですか、そこに関してはちょっと今後の検討課題とさせていただければと思います。","voiceIndex":238,"id":"exchange-105"},{"speaker":"芹澤委員","kind":"質問","question":"非常に前向きなご答弁をありがとうございました。続いて、認知症カフェについてもお伺いをします。先輩も入ると言っていただいていますので。ご見解をお聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"認知症カフェの名称に関して、それから認知症検診のスタイリッシュな受診率向上に向けた取組ですが、名称に関しては、カフェに関してはまだ歴史が浅く、今、箇所数を少しでも増やしていきたいという思いがありますので、これまでのなじみの度合いですとか。","voiceIndex":240,"id":"exchange-106"},{"speaker":"芹澤委員","kind":"質問・要望","question":"様々ありがとうございました。最後、医療的ケア児についてちょっと駆け足でお伺いをいたします。医療的ケア児支援法が昨年制定をされまして、本会議の中でも、これから品川区で２番目の児童発達支援センターをつくっていきたいというようなお話があったかと思います。現状、ほかに候補がどういったものがあるのかをお聞かせいただきたいと思います。","respondent":"松山障害者福祉課長","answer":"委員お尋ねの、２か所目の児童発達支援センターの整備検討ですが、今のところ、候補地といたしましては大原児童センターということを考えております。","voiceIndex":242,"id":"exchange-107"},{"speaker":"芹澤委員","kind":"意見","question":"ここ大原児童センターとしては、児童センター機能と、あとこの３階建ての１階にインクルーシブひろばベルがあって、ここから児童発達支援センターを入れるとなると、簡単な単純な発想で言えば何かをどかすというふうな話になってしまうと思うのですけれども、ぜひこれ、インクルーシブひろばベルは特に残していただいて、この窓口が一つで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":244,"id":"exchange-108"},{"speaker":"高橋（し）委員","kind":"質問","question":"２４５ページ、児童相談所移管推進事業で、区立の児童相談所の開設に向けて非常に尽力されていると伺っています。それで、これまで２３区が一体となって取り組んできた区立児童相談所開設、その一体化を少し乱すというか、そういう状況ではないでしょうか。区長会としても、２３区一体となって進めてきたことに関してどのようなご意見が出たのでしょうか。もしありましたらよろしくお願いします。","respondent":"加島児童相談所移管担当課長","answer":"こちらにつきましては、児童福祉主管課長会等におきまして、令和３年７月に国のほうが、児童相談所の管轄区域人口を１所当たり５０万人とするという人口参酌基準を定め、それを踏まえての動きだという説明を受けております。","voiceIndex":246,"id":"exchange-109"},{"speaker":"高橋（し）委員","kind":"質問","question":"一方２３区はこれまでの流れで、身近な一番の担い手として区立児童相談所を開設する、そういう役割分担があると。このままでは一枚岩で進まない可能性があるのではないでしょうか。区立児童相談所という、将来像が非常に見えにくくなってきていますが、その点についてはいかがでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"東京都におきましても、特別区部における児童相談所設置の動きを踏まえまして、広域行政の主体としての東京都の在り方、区部の児童相談体制の在り方を検討すると伝えてきておりますので、私どもはその中で東京都と協議し。","voiceIndex":248,"id":"exchange-110"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そういったことも含めると、２３区一体となって様々ありますが、同じ方向性を持って進めていってほしいと思います。これは要望です。確認したところ、Ｗｅｂｅｘというもので区の研修会に参加したり、ホストになって保護者会などが開けると。しかし、情報推進課からパソコンを借りてきて、それで現場の保育園で使うと伺っています。この認識でよろしいでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"Ｚｏｏｍに関しては、各園のネットワークに接続できるパソコンであれば、ゲストであれば入れるというようなところです。","voiceIndex":250,"id":"exchange-111","title":"議員研修会の内容と所要時間"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、各園が保護者会を自分のところのパソコンでやろうと思ってもできない、あるいは各園の様子を放映というか、オンラインで流そうとしてもできない、そういう状況だと思います。これはコロナ禍での影響だと思いますが、保育園・幼稚園では、そういった状況に関して、そういった今のネット環境についてどのようなお考えをお持ちでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"区立保育園・幼稚園では、例えば常に使える状態になったときにどういったことができるのかとか、仮にそうなった場合にどういった用途、頻度で使うのかというところを分析しながら、また区全体でいうとセキュリティ等々問題もありますので、情報システムの部門と連携を取りながら。","voiceIndex":252,"id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、情報推進課としては、このような、例えば４０園あるわけです。それで貸出し用のパソコンが９台か１０台しかないという、そういうような状況ですが、公立小学校のようなネット環境の状況の改善に向けて、公立小中学校のＺｏｏｍみたいな体制は不可能なのでしょうか。","respondent":"堀越企画部長","answer":"今は、セキュリティの理由から使えないという状況ですので、技術の状況を見ながら、今後検討していくと、そういう考え方です。","voiceIndex":254,"id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひ検討して、保育教育活動の幅が広がることを要望いたします。ということで最後になりますが、巡回保育ですが、決算特別委員会で要望したように、５歳児の方々に学校心理士が、全て巡回保育が行けるようなことになりました。予算化していただいて、本当にすばらしいことです。小学校との連携について、一言だけお願いします。","respondent":"若生保育支援課長","answer":"今後も就学時につなげる対応を充実してまいりたいと思います。","voiceIndex":256,"id":"exchange-114"},{"speaker":"若林委員","kind":"質問","question":"来年度組織改編が、この高齢者、特に認知症にかかる部分で改編がされるということで、総務委員会で報告がありましたので、これについて、どのような視点で、問題意識で、この改編に当たられたのか、そこら辺、どういう変化を起こそうとしているのか、また変化を起こさないようにしているのか、いろいろな角度があると思いますけれども、まずはそこをお聞きしたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"第八期品川区介護保険事業計画におきましては、認知症高齢者とともに生きる総合的な施策の推進を基本的な方針の一つとして掲げております。認知症施策では、共生と予防を両輪として政策を進めることとしておりまして、現在、高齢者地域支援課では介護予防事業を運営しております。","voiceIndex":260,"id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"分かりました。そうしますと、ちょっと先ほどの流れですが、認知症検診、物忘れ検診という、いろいろありますけれども、これのネーミングは、今ご答弁いただいた所管のほうで行われるというようなことで確認をしていいのかどうか。これはちょっと確認します。この新生寿会、また、きのこエスポアール病院の専門的な認知症ケアのノウハウというものはどういうものなのか、お知らせいただきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"東五反田地域密着型多機能ホームですけれども、こちらは、運営主体の母体のほうが、そもそもそういった認知症に長けている母体というところがありまして、今回、ミーティングセンター３か所分の開設支援経費を予定しておるのですが。","voiceIndex":262,"id":"exchange-116","title":"議員研修会の内容と所要時間"},{"speaker":"若林委員","kind":"質問・要望","question":"それはもう、研修の講師とか内容というのはもう千差万別というのか、認知症はいろいろな研究機関があったり、当然民間も研究していて、ちょっと書物を読んだだけでも、これは様々な、学説とは言わないけれども、角度があったり、どれが正しくてどれが、間違っているのはないかもしれませんけれども、そういった中で、こういった各品川区内のそういう入所・通所施設の、いわゆるノウハウといったものが。","respondent":"宮尾高齢者福祉課長","answer":"東五反田地域密着型多機能ホームを運営している社会福祉法人新生寿会につきましては、ちょっと先ほどの答弁と重複する部分あるかもしれませんが、認知症のケアの分野についてはとてもたくさんの知見、ノウハウを有している法人ということで、私どもも。","voiceIndex":264,"id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新年度に対象拡大とはならないのか、伺いたいと思います。この支援法の考え方にすべきだと思うのですけども、なぜ世帯の収入とするのか、障害者総合支援法や障害者権利条約にも、この取り方というのは合わないのではないかと思いますけれども、改めて支援法の利用料の考え方で、この利用料は選定するべきではないかと思いますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"新年度の対象に変更があるかということですが、対象者についてもまだ引き続き検討しておりますので、新年度については対象はこのままにしています。続きまして、利用料金についてです。利用料金も同様に、現在検討を行っているところです。","voiceIndex":267,"id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"こういう方、重度障害の方が、家族が倒れたときに、その重度障害の方も巻き込んでしまうし、家族の方とともにその障害者の命にも関わる問題なので、これをぜひ対象になるよう拡大してほしいということで、私はずっと取り上げているのですけども、なぜやらない、なぜずっと検討というのが続いているのか分からないのですが、こういうところまで拡大することは必要だとは考えられないのか。","respondent":"松山障害者福祉課長","answer":"現在も事業の整理を行っておりますので、まだ引き続き検討はしていくです。","voiceIndex":269,"id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"重度障害の方を見られている方は高齢とは限らないのです。それから続けてお聞きしたいのが、医療的ケア児等支援体制協議会についてなのですが、２０１８年度までに国から設置を求められていたのですけど、品川区は会議が始まったのかどうなのかというのをちょっと伺いたいのです。第４回定例会の答弁では、今年度中に開催予定ということだったので、それが行われたのかどうかを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"医療的ケア児等支援関係機関連絡会の開催についてですが、２月に実施予定で組んでおりましたけれども、コロナウイルスの感染症の影響により、書面開催という形にしています。委員の方々には今、実際に資料をお送りしまして、ご意見をいただいている途中です。","voiceIndex":271,"id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害児者総合支援施設のぐるっぽについて伺いたいと思います。この間、当事者、家族にどのような説明を行い、その受け止めはどういう状況なのかを伺いたいと思います。１０月には事業者が変わるわけですけれども、その後でも、品川区の障害者福祉を今後どう展開していくのかという点からも、今回の事業者変更については、区としても検証が必要ではないかと私は思いますけれども、いかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"障害福祉計画推進の中で、様々な方向性について検討してまいりたいと考えております。","voiceIndex":273,"id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"事業者が変わるわけですけれども、職員がそのままどれぐらい残るのか、今の事業者から今度新たな事業者に変わるに当たって、今の働いていらっしゃる方が次の事業者のところに移っても職員がそのまま残るという割合がどれくらいあるのかについてもお聞かせいただきたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"職員の状況ですが、法人の人事に関することですので、こちらでは回答は差し控えさせていただきたいと思います。","voiceIndex":275,"id":"exchange-122"},{"speaker":"西村委員","kind":"質問","question":"２４３ページ、子育て支援事業全般、地域子育て支援グループ活動支援、２４５ページ、すまいるスクール運営費、２５２ページ、児童保育費、２５７ページ、運動・体力向上事業を時間が許す限り順不同で伺ってまいります。スポーツ体験の拡充、ボッチャセットの全園配備が次年度行われますが、実施が区立保育園だけの理由と私立園の検討があるのかどうかお伺いいたします。","respondent":"若生保育支援課長","answer":"私立保育園は民間事業者等の運営ですので、区立園のように一律に実施するということは難しいところではありますけれども、園長会等でよい取組事例などを横展開していったりですとか、東京２０２０大会のレガシーを子どもたちへ引き継いでいけるように。","voiceIndex":278,"id":"exchange-123"},{"speaker":"西村委員","kind":"質問","question":"レガシー教育はぜひとも全園でお願いをしたいと考えています。子どもたちの記憶力が大変すばらしいですので、この年数回の取組でも大人が驚くほど覚えているものだと思います。各保育園が選ぶスポーツの選択のバランスに人気差はあるのか、また、ホッケー、ボッチャはオリンピック・パラリンピックと区の関わりがありますが、ラグビーが導入された理由を併せて教えてください。","respondent":"初貝保育教育運営担当課長","answer":"今、委員ご指摘のとおり、各競技に関しては、保育の状況のところ、園庭が広いとかそういった状況を踏まえて、保育園が選ぶというところで、令和４年度の実施予定としてはホッケーが８園、ラグビーが２２園、ボッチャが９園というような、今のところの予定です。","voiceIndex":280,"id":"exchange-124"},{"speaker":"西村委員","kind":"質問","question":"会派の野球・サッカー好きの委員からも声が上がっておりまして、いろいろなスポーツに触れてほしいと思う一方で、せっかく楽しいと思えたスポーツを私としても長く楽しんでほしいと考えます。そういう意味でいえば、区内でラグビーを楽しめる場所は少なく、サッカーや、日常的に公園でも遊んでおります野球、バスケットボールなどほかの競技でもいいのではないかと考えますが、いかがでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"その辺りは、講師がどういう方がいるかとか、あとは施設の環境がどうかとか、あとは子どものところです、どういった形だったらやれるのかとか、そういったところを総合的に考えまして、今後の展開を様々検討していきたいと思います。","voiceIndex":282,"id":"exchange-125"},{"speaker":"西村委員","kind":"提案","question":"次に進みます。子育て支援事業全般から夢食堂事業という取組をご提案させていただきたいと思います。実際に区内で実施してくださっている店舗に伺いまして、この夢食堂の新たな取組を知りました。私がお伺いした店舗はもんじゃ焼き・鉄板焼きのお店でして、子どもたちに焼いてもらい、食事後の配膳は子どもたちが自分で行っておりました。すばらしい取組だと思いますが、区の見解とご意見をお聞かせください。","respondent":"廣田子ども育成課長","answer":"行政ですぐできるか、どうできるかというところについて、今すぐご提案はできないのですけれども、今、地域の団体と意見交換会などを開いたりしておりますので、いろいろな取組をしている、様々な工夫されている状況について、行政も入り、地域の方も入って意見交換をしながら。","voiceIndex":284,"id":"exchange-126"},{"speaker":"西村委員","kind":"質問","question":"逆に今だからこそ、困っている人に手を差し伸べないと手後れになるかもしれないという思いからだと伺っております。地域力の循環がテーマだと思っています。このような課題解決に向けても新しい取組へのご検討をお願いしたいと考えています。次に進みます。コロナ禍で運営に苦慮されていた点もあると思いますが、昨年度の実績と、この地域子育て支援グループのコロナ禍の現状について伺います。","respondent":"廣田子ども育成課長","answer":"令和３年６月から開始したのですけれども、１月末現在で９団体の申請がありまして、外遊び事業であるとか、木育勉強会、親子サロン、障害や難病などの家族の会など６団体に助成したところです。","voiceIndex":286,"id":"exchange-127"},{"speaker":"西村委員","kind":"質問・要望","question":"すみません、私も少し確認をさせていただきたいと思います。少し派生しますが、修学旅行を引き受ける宿とか施設でも、児童のアレルギー対応に大変苦慮をされているということは伺ったことがあります。とはいえ、先進事例も大分できてきました。私がお調べした限りですが、様々な導入方法があれど１１区かそれ以上、広まってきているかなというふうに思っております。ご検討をお願いしたいと思います。","respondent":"廣田子ども育成課長","answer":"学童保育等でお弁当等を出しているというところについては、令和元年度に区で調査を１回しております。その当時は１５区ぐらいあったのですけれども、いずれも保護者会・父母会が実施しているというような内容でございました。","voiceIndex":288,"id":"exchange-128"},{"speaker":"西村委員","kind":"質問","question":"続きまして、保育園に関して伺ってまいりたいのですが、先ほど募集状況のご報告もありました、保育園の申請に関して伺いたいと思います。品川区は、申請書にある希望園８園を全て書かなくてもよいと認識をしています。全て書かないと受理されない自治体もある中で、育休延長希望かどうかをチェックできる欄も設けています。品川区が８園全て記載することを必須としていない理由を教えてください。","respondent":"立木保育課長","answer":"保育園の入園に関しましては、それぞれご家庭のご事情がある中で、ご希望される園の中で入園が決まっていただければいいという形で、ご利用される方に沿った入園制度を組み立てているです。","voiceIndex":290,"id":"exchange-129"},{"speaker":"西村委員","kind":"質問","question":"「どうして」と伺うと、「そこの園しか行きたくなかったから」と、そういったような個々の事情もあると考えています。補正予算の審査でも質問させていただきましたが、保育園の待機児童問題に関しては一定の成果が出ており、一区切りとして捉えてはどうかと考えています。新たな課題に向けて議論していくタイミングにあると考えますが、もう一度ご答弁をお願いいたします。","respondent":"立木保育課長","answer":"今後も必要な数は用意しつつ、より一層質の向上や多様なニーズへの対応など、今後もしっかりやっていくことに併せまして、ニーズの動向を注視するとともに、これまで総合的な待機児童対策をやってきておりますので。","voiceIndex":292,"id":"exchange-130"},{"speaker":"西村委員","kind":"質問・要望","question":"こういったお母さんたちの現状が年々変わってきているというのも感じますし、実際にこの間も質問させていただきましたが、点数がどんどん下がっていくと、入れる指数が下がっていくということも現実的に起こってきているというふうに思います。ちょっと難しい質問かもしれないのですが、何かそのような機会をつくっていただけないかなと思うのですが、ご答弁お願いできますでしょうか。","respondent":"若生保育支援課長","answer":"今後とも、そういったことも含めまして、感謝の気持ちの伝え方というところも、区としてどういった形がいいのか、今後、区立・私立含めまして、きめ細かく状況を日々聞き取っていく中で、できる対応を行っていきたいと考えています。","voiceIndex":294,"id":"exchange-131"},{"speaker":"西村委員","kind":"意見","question":"全ての園を数えると大変な職員の数になると思いますが、ぜひとも皆様にそういった感謝の気持ちを伝えられる機会をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":296,"id":"exchange-132"},{"speaker":"藤原委員","kind":"質問・要望","question":"２６９ページ、生活保護費で、これ課長、具体的な例を挙げて伺いますが、今、何十年も会わなかった親戚の方から、その方が亡くなられて遺産が入る。それと、２１５ページの、重層的支援体制整備検討経費というのですけれども、これ、課長、しあわせ創設プランと金額が同じなのですけれど、これでいいのでしょうか。そう考えるならば、課長が考える幸せって何ですか。どういうのが幸せか、教えてください。","respondent":"櫻木生活福祉課長、寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"委員にご指摘いただいたとおり、通常の就労収入とは違って遺産については申告の義務がないと思われる方も若干いらっしゃる可能性がありますので。重層的支援体制整備の検討です。来年度の品川介護福祉専門学校の入学予定者数ですが、現時点で１４名というふうに聞いております。","voiceIndex":298,"id":"exchange-133"},{"speaker":"藤原委員","kind":"質問・要望","question":"１４名、これは減りましたね。それで、前回の決算特別委員会のときも伺いました。何か変わっていくというように伺ったのですけれども。こういうふうに継続をしていただいて、給料面の改善をしていただきたいと私は思うのですが、改めてそこをお伺いします。困難な課題、これは、ここ保健所とか男女共同参画センターでもできないということで、こういう形でしあわせ創設プランをつくったのでしょうか。","respondent":"宮尾高齢者福祉課長、寺嶋福祉計画課長","answer":"それから報酬改定に関してですけれども、２月から９月の間は補助金の扱いでやりまして、１０月以降は、今の政府のほうが、臨時の介護報酬の改定を予定しているというところですので。こういったときに、それぞれの部署が、直接ではないのですけれども、一歩手を伸ばせば何か支援ができるという、そういう部署が５つ、６つ集まってきますと、何かしらの支援につながる可能性があるというところに着目しまして。","voiceIndex":302,"id":"exchange-134"},{"speaker":"藤原委員","kind":"質問・要望","question":"幸せ、いいですね。ただ、課長、あの窓口に座ってというのは、なかなか相談できないので、新しくブースをつくるとか、そういう相談ができるような、相談しやすい場所をぜひつくっていただきたいと思います。日本の平均の年収は４３０万円ぐらいです。だから行政で、政治で、そこを変えていっていただきたいという思いで、何回も何回も何回も質問させていただいているので、その辺について改めてお伺いします。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"ワンストップ、ブースというご指摘をいただきましたけれども、先進の自治体の事例などを見ますと、これが必ずしも今ちょっとそういう方向性と若干違っているところも出てきておりまして、例えばその専門性がないと。一方で今回、９月までの補助金の対応、それから１０月以降の臨時の報酬改定、こういったことをしっかりと事業所の方たちに周知をするということが、まず一つ、我々に課された大きな宿題だというふうに思っておりますので。","voiceIndex":305,"id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"２０１８年の国保制度の広域化から４年が経過しましたけれども、それ以来、国保料が最大の額に今回なっているということです。だからこそ、区民に最も身近な自治体が、国保を社会保障として、命と健康を守るという本来の役割を果たすためにあらゆる努力をして軽減に踏み出すべきだということも、繰り返し求めてきました。ですので、区でできることなのになぜやらないのか、伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"ただいまの、法定外の繰入金のお話だと思いますけれども、それについて、なぜやらないのかですが、実際には、区としましてはこれまでも、平成３０年から令和元年、令和２年、令和３年と、一般会計からの繰入金につきましては、７億円、８億円というような形で。","voiceIndex":309,"id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"大幅に減らしてきているのです。それを元に戻すだけでも大きな軽減につながるということで私たちは求めています。法定外繰入を、７億円、８億円とやられてきたと言いますけれども、さらに、この平成２２年、またその前、もうとにかく３０億円台を入れてきた、そのときに戻せるべきなのになぜやらないのかというのを聞いているのです。お願いします。","respondent":"池田国保医療年金課長","answer":"法定外の繰入金についてですけれども、実際にはこちらの繰入金の額というものは毎年の繰越金にもよるものでございまして、たまたま、今年の繰り越した金額が９億３,０００万円という大きなお金がございましたものですから、それを法定外繰入金に使わないようにということで。","voiceIndex":311,"id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"多くのとおっしゃっているのは、その７億円、８億円ということですよね。ですので、私たちは、こんなに値上げされては本当にもう負担の限界だということで、さらなる法定外の繰入れをということで求めているのです。払えずに、もうやむなく最後、執行停止とかにされる方もいると思うのですけども、執行停止処分をした数、そして滞納者、それから短期証、資格証、そして差押件数をそれぞれ伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"令和２年度につきましても、１億９,０００万円ほどを執行停止させていただいたところでございまして、実際に令和３年度につきましても、まだこれは最終的な数字は出ておりませんけども、同様な数といたしまして、２億円程度の執行停止の額が見込まれているところです。","voiceIndex":313,"id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"執行停止は数を聞いたのです。昨年度はなくて、今年度は１.９億円ということで、東京都にも財政支援、激変緩和の措置を約束どおり入れるように求めるべきではないでしょうかということをお聞きしたいと思います。この年金収入２００万円以上の方が２割負担になるのですけれども、年金収入２００万円の方が窓口負担２割になるということ、この負担感、区はどのように考えているでしょうか、教えてください。","respondent":"池田国保医療年金課長","answer":"その中で今回、国のほうの施策の中で、現役世代の負担を減らすということをさらにやるということで、２割負担というものが今年の１０月から実施されるですので、これはもう高齢者だけをということではなく、現役世代の方も守らなければいけないことですので。","voiceIndex":315,"id":"exchange-139"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、現役世代の軽減にもつなげるのだと言っていましたけれど、現役世代の軽減は今回、年で７００円だけなのです。２割負担になることで、受診を控えて薬も減らす、こういう人が生まれるのは容易に想像できることではないでしょうか。国も区でも、医療費を削減していこうということで様々な健康対策をされていますけれども、こういうことにも矛盾していくのではないかと思いますけれども、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"後期高齢者医療の保険料につきましても、今回２割負担に始まるということで、６００円ほどの負担が軽減されているということで、こちらも軽減をされていますので、ですからこれでいきたいと考えています。","voiceIndex":317,"id":"exchange-140"},{"speaker":"大沢委員","kind":"質問","question":"お願いします。最初に、児童相談所ですけれども、いろいろと費用の部分、議論には出て、質疑でも聞いておるところですけれども、１点だけ、一番根幹となる人材、この品川区立児童相談所設置に係る検討課題の中で、人材の育成・確保というのは、当たり前のようでまだこの委員会では語られていないような気がしますので、改めて現状について伺いたいと考えています。","respondent":"加島児童相談所移管担当課長","answer":"開設に向けてと申し上げましたけれども、開設はゴールではなく、開設後の安定的な運営を視野に入れて、今後も最大限、人材の確保、育成に取り組んでまいります。","voiceIndex":320,"id":"exchange-141"},{"speaker":"大沢委員","kind":"質問","question":"以前、人材の確保に困難を要しているということで伺ったことがありますけれども、そこについてどのような工夫をされ、どのような考えの下に、人材の確保の取組をされているのか、教えてください。","respondent":"加島児童相談所移管担当課長","answer":"そういった知識・経験を持つ職員は、今、残念ながら区のほうにはおりませんので、人事課と協議いたしまして、先ほどの答弁と一部重なりますが、任期付採用に新たに取り組み、児童相談所の業務、知識、経験を持つ職員、開設時に即戦力となり。","voiceIndex":322,"id":"exchange-142"},{"speaker":"大沢委員","kind":"質問・要望","question":"いずれにしてもこの児童相談所、恐らく人材確保にかなり困難を要するところだと思いますので、大変なご苦労は理解をしております。次へ行きます。高齢者福祉のほうで、いつもの団塊の世代についてを中心に伺いたいと思うのですけれども、２０２５年、団塊の世代が後期高齢期を迎えるわけでありまして、この事象について、区では、起こるだろう問題を予想してどのように備えていくかが必要であると思うのです。","respondent":"宮尾高齢者福祉課長","answer":"介護認定をされる方の年齢はやはり７５歳を境に大きく、申請率といいますでしょうか、それが上がってくるというところで、当然その先に、皆さん介護保険をお使いになられて、そうすると給付費の上昇が見込まれるです。","voiceIndex":324,"id":"exchange-143"},{"speaker":"大沢委員","kind":"意見","question":"私はよく、高齢者像の変化ということで何回もお話ししますけれども、戦前、戦後を境に高齢者像の変化があったと。人口が多いので、当然、住まいにおきましては、ちょっと聞いたところでいうと単身が増えているということですので、この２本の柱を解決しなければ大きな柱になってくるとは思うのですけれども、そこのところはどういうふうに捉えられて、どういうふうにお考えになっていらっしゃいますか。","respondent":"宮尾高齢者福祉課長","answer":"そのために様々、その在宅生活を支援し続けるためにどういった対策が必要か、高齢者の方が増えていくとどういうことが想定されてくるのか、こういうことをしっかり捉えて今後も政策を推進してまいりたいというふうに考えております。","voiceIndex":326,"id":"exchange-144"},{"speaker":"大沢委員","kind":"意見","question":"私、相談を受けるのですけれども、単身者で住居に困ったということで、私のところはなかなか、ということでお話しされているのです。本区においては昨年の３月より、それを取り扱っているような気配というか、動きがないのですけれど、それは何か、当然理由があるのでしょうけれども、それについてお聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"高齢者の方の住まいですけれども、様々な種類があります。特に、軽費老人ホームにつきましても、例えば区のほうで設置をしないとか、そういうことを決めている考えというところはございません。","voiceIndex":328,"id":"exchange-145"},{"speaker":"大沢委員","kind":"質問","question":"今、軽費老人ホームというお話いただきまして、私が聞いたのは、都市型軽費老人ホームということで、都市型軽費老人ホームと単なる軽費老人ホームでは、いろいろなサービス、取扱いがいろいろと違ってくると思うのですけども、そこのところは、今ご一緒に考えられた答弁ではないですよね。もう１回お願いします。","respondent":"宮尾高齢者福祉課長","answer":"軽費老人ホームには、いろいろ、都市型、あるいは都市型でない軽費老人ホームと、いろいろ種類がある中で、一概に、これを選択する、これを選択しないという考え方ではなく、それぞれの類型の長所、短所があろうかと思いますので。","voiceIndex":330,"id":"exchange-146"},{"speaker":"大沢委員","kind":"質問","question":"この件について、平成２１年に群馬県渋川市で起きた、端を発するわけでありまして、この件については、都市型が都のほうで推奨している、近隣区でもこれについての取扱いは行っているのですけれども、品川区ではやはり政策がいろいろあろうかと思います。そこの政策についての、１年経っていますけれども、政策についての取扱いや俎上に上げてない部分がありましたら、考えがありましたら教えてください。","respondent":"宮尾高齢者福祉課長","answer":"様々、類型がある中で、長所、短所をしっかり研究してまいりたいと思います。","voiceIndex":332,"id":"exchange-147"},{"speaker":"塚本委員","kind":"質問・要望","question":"それから２３５ページ、認知症高齢者支援事業、主に、徘回高齢者家族支援といったところで質問をします。予算額としては９２万４,０００円というところで、年間でいくとそんなに大きな額というふうにも捉えられませんけれども、これは定員みたいなものは設定されているのでしょうかということをまず最初にお伺いします。","respondent":"松山障害者福祉課長","answer":"障害者医療ショートステイ事業の利用定員ですけれども、特に利用定員という考え方ではなく、やはり医療機関の空き病床を利用するため、ご利用につきましては最大７日間と見込んでおりまして、年間８人程度をまずは想定しようです。","voiceIndex":335,"id":"exchange-148"},{"speaker":"塚本委員","kind":"質問・要望","question":"プライオリティというか、要するにほかの患者さんと医療ショートステイを望む人とが来て、両方の要望が同じ日にあったときに、その辺をどう調整していくのかみたいな話というのはある程度固まっているのでしょうか。","respondent":"松山障害者福祉課長","answer":"森山リハビリテーションクリニックと協議したところ、７日間ずっとベッドに寝ているのではなく、リハビリを提供するという形を医療機関が考えておりまして、何とか地域医療をその拠点でやりたいという思いもありますので。","voiceIndex":337,"id":"exchange-149"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。非常に大切な事業だと思いますので、よろしくお願いしたいと思います。次に、障害児者福祉施設運営費というところなのですけれども、第６期品川区障害福祉計画、ここには、国の大きな方針として、障害者の方をなるべく地域で支えながら、地域での暮らしをという中で、その地域で支えていくために地域生活支援拠点等の整備といったところが、この計画の中に述べられております。","respondent":"松山障害者福祉課長","answer":"強度行動障害がある障害者の方へのショートステイの受入れ体制です。区内につきましては、区立かがやき園、それからかもめ園のショートステイで対応しています。","voiceIndex":339,"id":"exchange-150","title":"議員研修会の内容と所要時間"},{"speaker":"塚本委員","kind":"質問","question":"今、そういった形での受入先はあるよということだと思うのですけれども、実際になかなか、強度行動障害と言われる方々については、対応するスタッフの方々もたくさん必要になる。区としてここら辺の受入れについての様々な調整というか、こういったところについて、どういった認識をお持ちか、お伺いいたします。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、その方の状態ですとか、あるいは同日、同じくショートステイを利用される方の状況等を考慮して、難しい場合もあります。なかなか区内だけでは難しく、都外だったりする、こちらのほうで探して、何とかショートステイで当該施設が対応する場合もあります。","voiceIndex":341,"id":"exchange-151"},{"speaker":"塚本委員","kind":"質問","question":"例えば区内の近場で預けられれば、そちらのほうがはるかに望ましいわけですが、こういった強度行動障害等にも配慮した施設の整備というようなことを、新しい建物を建てるとかという、施設を造るということはちょっと現実的ではないと思いますけれども、既存の施設の中でそういったことの整備ということを進めていくというようなことは、どの程度なし得る。","respondent":"築山障害者施策推進担当課長","answer":"ハード面では、ぐるっぽのショートステイで、強度行動障害の方も想定した造りとなっておりますので、今後の新たな体制の中で受入れができるよう進めてまいりたいと考えています。","voiceIndex":343,"id":"exchange-152"},{"speaker":"塚本委員","kind":"質問・要望","question":"今、ぐるっぽというお話が出ました。これとあとは同じようにこの徘回高齢者の見守り的なシステムで、品川くるみ高齢者見守りネットワーク、この２つが事業としてあると思うのですけども、これの利用状況、それからこれを実際に利用してみての、利用した方々からの、効果というのですか、どの程度この徘回というものに対応がなされるものなのかということで状況をお聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"アイテム、それから探索システムの利用状況と利用者様の声です。見守りアイテムにつきましては、今年１月の末現在で、ご登録をいただいている方が４６５人、それから探索システムのご利用者の方は、同じく１月末現在で、３１人の方にご利用をいただいているところです。","voiceIndex":345,"id":"exchange-153"},{"speaker":"塚本委員","kind":"質問・要望","question":"ＧＰＳのほうが３１人ですか。こういったことに対しての、先ほどちょっと出てきた、認知症ミーティングセンター等も、そういったことにも一つ寄与する部分もあるかなとも思うのですが、その辺の徘回高齢者家族支援というところでの近隣との関係といったところについても、どのようなことがなされるべきというふうにお考えか、お聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"そういったときにこそ、私ども高齢者福祉課があり、在宅介護支援センターがあり、あるいは、４月から始めるミーティングセンターがあり、はたまた認知症カフェがあるというところで、そういったいろいろな場で。","voiceIndex":347,"id":"exchange-154"},{"speaker":"塚本委員","kind":"質問・要望","question":"それで、ちょっと時間があまりもうないので要望だけにしておきたいと思いますけれども、先ほども別の委員からちょっとありましたが、認知症サポーター、この方が今１万８,０００人以上登録されているというところで、この認知症サポーターの方というのは、中には千差万別、いろいろな方がいますけれど、サポーターというぐらいなので、何か自分がこの講習を受けたと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":349,"id":"exchange-155"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は２２９ページ、障害児者総合支援施設と、２６７ページ、私立幼稚園、時間があれば保育園について伺います。１０月から運営者が福栄会に変更されます。現事業者を３月いっぱいで辞める職員がそれなりにいるというふうに伺いました。このようなことはないですよね、というのを伺いたいと思います。それから、現在、就労支援、生活介護とか地域活動支援等が混在している状況があると伺いました。","respondent":"築山障害者施策推進担当課長","answer":"研修につきましては、医療的ケアや、重度心身障害者の方に対応できるよう、職員の外部研修を予定しておりまして、現在コロナの状況で、本来でしたらステーションの中に入ってということを考えていたのですけれども、こういう状況でできないので。","voiceIndex":351,"id":"exchange-156"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ、今の指導のところはしっかり行っていただきたいなと。それから、「待機者が多くて、待機の期間も長くて、どうやって解決してくれるの」ということも伺いました。これはちょっと残念なので、しっかりそこは、別に競うつもりはないけれども、結構聞くことがあったので、そこら辺の今、重度の話がちょっとあったけれども、そこら辺のところをどうしていくのか、お伺いしたい。","respondent":"築山障害者施策推進担当課長","answer":"児童の相談において、待機期間が長いという点につきましては、新たな体制では、子ども発達相談室と障害児相談支援事業の事業連携を強化しまして、共同して取り組むことで、相談から支援への流れを見直し、インテーク期間の解消を図っていく考えです。","voiceIndex":353,"id":"exchange-157"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ、よろしくお願いしたいと思います。その中で、来年度の予算でありますけれど、改築計画、先ほども西本委員への答弁で、１階は人が下りてきて相談とか受付とかそんな感じになると、地下の浴室とかいうのは伺いました。それはもう短期のほうがいいわけですけれど、音の問題等もあるので、そこら辺はどう受け入れられると思っているのかということ。これの考え方をぜひ教えていただきたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"利用者に迷惑がかからないよう、動線を分けての工事を考えております。期間につきましては、令和４年度に設計も含めての予定となっておりますので、その中で利用者に配慮した工程を考えたいというふうに考えております。","voiceIndex":355,"id":"exchange-158"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひよろしくお願いしたいと思います。今回、入園希望者が１８園中１３園が定員割れ、ここ３年は１００名程度で減だったのでありますけれど、今回は４７０名程度が減となりました。２園の個別事情もありましたが、それを差し引いたとしても、３５０名程度の減となっていたのかなと考えています。この減の要因をどう捉えていらっしゃるのか、まずそれを伺いたいと思います。","respondent":"若生保育支援課長","answer":"広く区民の皆様の目に触れるような形で広報等に力を入れるなどの、そういったような対策も必要ではないかと考えているところですので、区としてできることをまた検討していきたいと考えています。","voiceIndex":357,"id":"exchange-159"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私もこの間、品川区の２園、他区の１園の園長から話を伺いました。そこら辺のところの支援もぜひ考えていただきたいなと思いますし、あと、幼稚園はやはり恵まれているという環境があるのは事実だと思っています。それは、最後にここだけは思っていただきたいのは、区も幼稚園の団体から要望を毎年伺って支援していただいていると考えています。我々も要望を伺い、区に伝えてきております。","respondent":"若生保育支援課長、渡辺委員長","answer":"幼稚園の全体の在り方ですけれども、私立幼稚園に関しましては、乳幼児教育の重要な部分を担っていただいていると認識していますので、区立の在り方と含めて今後検討してまいりたいと考えています。以上をもちまして、本日予定の審査は全て終了いたしました。次の会議は、１０日木曜日、午前１０時から開きます。本日はこれをもって閉会といたします。","voiceIndex":359,"id":"exchange-160"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1150#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":126046,"voices":361}}]);
